(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-moe-quant"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-1\">一 · 从一次 decode 尾延迟失控说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-2\">二 · 机制：16 元素块共享 FP8 scale 的微缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-3\">三 · 收益落在哪条账单上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-4\">四 · 不适用与反例：outlier 与 scale 开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-5\">五 · 工程判断：先定位瓶颈再决定是否上 4-bit</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-6\">六 · 一次路由漂移引发的尾时延雪崩：NVFP4 的边界在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-7\">七 · 离线校准：专家权重的块级 scale 落盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-8\">八 · 激活侧量化：per-token 分组与 scale 随行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-9\">九 · All-to-All：4-bit 载荷与索引的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-10\">十 · tcgen05 FP4 MMA：分组 GEMM 与累加前反量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-11\">十一 · combine 与回写：反量化回 BF16、KV cache 不动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-12\">十二 · 量化流水线的断点：从校准到 combine 的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-13\">十三 · 公式三项：块内归一、E2M1 舍入、双 scale 还原</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-14\">十四 · 激活侧的对称推导与 per-token 分组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-15\">十五 · 伪代码：从校准到分组 GEMM 的可实现骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-16\">十六 · 精度推导：误差如何在块内被约束、在层间被放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-17\">十七 · 与 KV cache、combine 的边界：哪些张量不进 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-18\">十八 · 工程判断：什么条件下这套公式值得落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-19\">十九 · 请求形态：NVFP4 的收益只在“专家权重主导”的形态里成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-20\">二十 · 长度分布：长上下文放大权重项，短上下文放大激活项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-21\">二十一 · 并发与批大小：连续批处理把 scale 开销摊薄，但也把 outlier 风险放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-22\">二十二 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-23\">二十三 · 配方落地：把负载判据写进部署档位与监控项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-24\">二十四 · 负载配方：什么时候 NVFP4 真能兑现带宽减半</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-25\">二十五 · 硬件档位与并行拓扑的绑定关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-26\">二十六 · 量化方案的组合选择：权重离线、激活在线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-27\">二十七 · KV 策略与显存预算的分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-28\">二十八 · 调度参数：批大小、分块与 piggyback</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-29\">二十九 · 可复现的配置思路：从判据到参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-30\">三十 · 部署配方的边界：什么条件下 NVFP4 才真正兑现带宽收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-31\">三十一 · 显存与带宽账：收益先落在权重读取上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-32\">三十二 · 反量化 scale 的固定开销：小 batch 时先崩的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-33\">三十三 · All-to-All 通信：4-bit 激活让传输量减半，但尾延迟不按比例缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-34\">三十四 · 功耗与吞吐的耦合：FP4 MMA 的能效不是线性的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-35\">三十五 · 精度漂移的尾延迟放大：路由打分与逐层累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-36\">三十六 · 规模上去后哪里先崩：按 regime 排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-37\">三十七 · 带宽账本的另一面：NVFP4 在什么规模上先撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-38\">三十八 · 精度失败的三种形态：outlier、路由漂移、误差累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-39\">三十九 · OOM 与显存账本：量化省下的不是全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-40\">四十 · 批抖动与路由不均：吞吐曲线的锯齿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-41\">四十一 · 尾延迟尖刺的定位：从 P99 回溯到块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-42\">四十二 · 监控面与回滚阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-43\">四十三 · 量化误差如何沿路由链放大：诊断与回滚的工程抓手</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-44\">四十四 · 选型的第一维：把量化维度与路由维度解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-45\">四十五 · 决策表：五类相邻算法的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-46\">四十六 · 与 FP8 的取舍：精度预算怎么花</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-47\">四十七 · 与路由类算法的耦合：打分漂移是隐藏的选型成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-48\">四十八 · 适用条件清单与规模上限的定性判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-quant-sec-49\">四十九 · 选型边界：NVFP4 与 FP8、INT4 分组量化、AWQ/GPTQ 的分工</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:528px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 528.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">离线校准：对每个专家的权重按 16 元素块计算 FP8 scale，权重舍…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">运行时激活按 token 分组量化到 NVFP4，scale 随 toke…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">tcgen05 FP4 MMA 执行分组 GEMM，累加器为 FP32，块…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">combine 后激活反量化回 BF16 进入下一层，KV cache 仍…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-moe-quant-sec-1\">一 · 从一次 decode 尾延迟失控说起</h3>\n<p>某线上 MoE 推理服务在 FP8 权重方案下运行稳定，扩容到 NVL72 拓扑后，运维按线性外推增加副本数，结果尾延迟不降反升。排查发现：decode 阶段每个 token 都要把该 token 命中的全部激活专家权重从 HBM 读进 SM，专家权重占显存主体，单卡可驻留的专家数受容量限制，跨卡场景下激活专家还要经 All-to-All 取回。批大小一旦被显存带宽而不是显存容量卡住，增加副本只会摊薄每副本的并发，tokens/s 提升有限，而尾时延因排队抖动变差。FP8 已把权重压到 1 字节，但“每 token 读全部激活专家权重”这一条带宽账单没有变——这正是 NVFP4 权重激活微缩放量化要处理的具体问题：把权重与激活同时压到 4-bit，让 decode 阶段的专家权重读取时间和 All-to-All 传输量相对 FP8 近似减半。</p>\n<p>需要先把边界划清。这个算法不解决路由质量问题：容量因子、令牌丢弃、专家选择策略属于另一维度，量化只改变数值表示，不改变“哪些 token 去哪些专家”的决策逻辑，二者正交。它也不解决 KV cache 压力：KV cache 仍保持 FP8/BF16，长上下文场景的显存占用与带宽开销不因本算法下降。它更不解决预填阶段的计算密度问题——预填是大 GEMM、算力受限，收益主要落在 decode 的带宽受限区间。把 NVFP4 当成“万能加速开关”去覆盖所有阶段，是这类事故的常见误判来源。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-2\">二 · 机制：16 元素块共享 FP8 scale 的微缩放</h3>\n<p>NVFP4 的数据格式是 E2M1 加每 16 个元素共享一个 FP8 scale。离线阶段对每个专家的权重按 16 元素块计算 scale 并舍入：</p>\n<div class=\"formula\">$$w_{i}=\\text{FP4}\\left(\\frac{w_i}{s_b}\\right),\\quad s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}}$$</div>\n<p>运行时激活按 token 分组走同一套规则：</p>\n<div class=\"formula\">$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$</div>\n<p>分组 GEMM 在 tcgen05 上以 FP4 MMA 执行，累加器为 FP32，块内按 scale 反量化后再累加：</p>\n<div class=\"formula\">$$\\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</div>\n<p>关键在于 scale 的粒度：16 元素共享一个 FP8 scale，意味着块内动态范围被压缩到 E2M1 可表示的区间，而块间差异由 scale 吸收。相比 per-tensor 量化，这种做法把 outlier 的影响限制在单个 16 元素块内，不会让一个极端值拖垮整层权重的表示精度。代价是 scale 本身要随权重常驻显存、随激活进入 dispatch 缓冲，并在 MMA 前参与反量化——这不是免费的。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-3\">三 · 收益落在哪条账单上</h3>\n<p>decode 阶段每 token 需读取全部激活专家权重，批大小受显存带宽约束。权重从 1 字节降到 0.5 字节，专家权重读取时间近似减半，直接抬升 tokens/s；All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 减半，跨卡专家并行的通信开销同步下降。tcgen05 原生支持 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍——注意这是 MMA 吞吐，不等于端到端吞吐翻倍，因为反量化与 scale 处理会吃掉一部分收益。精度侧，微缩放精度损失在 MoE 上通常小于 1% 困惑度，这是该格式能上线的必要条件而非充分条件。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>FP8 权重方案</th><th>NVFP4 权重激活微缩放</th></tr></thead><tbody><tr><td>权重位宽</td><td>1 字节</td><td>4-bit（E2M1）</td></tr><tr><td>激活位宽</td><td>通常 BF16/FP8</td><td>4-bit（E2M1）</td></tr><tr><td>scale 粒度</td><td>per-tensor 或 per-channel</td><td>每 16 元素共享 FP8 scale</td></tr><tr><td>decode 专家权重读取</td><td>基准</td><td>近似减半</td></tr><tr><td>All-to-All 传输</td><td>基准</td><td>减半</td></tr><tr><td>MMA 吞吐</td><td>基准</td><td>可达 2 倍（FP4 MMA）</td></tr></tbody></table>\n<p>一个具体例子：某层有若干激活专家，decode 批内每 token 命中其中一部分。FP8 下这些专家的权重按 1 字节/元素读出；NVFP4 下同样元素数只读 0.5 字节，加上每 16 元素一个 FP8 scale 的额外开销（约 0.0625 字节/元素），总读取量仍显著低于 FP8。若该层是带宽瓶颈，tokens/s 的提升直接来自这段读取时间的缩短；若该层已被 MMA 吞吐卡住，收益则体现在 FP4 MMA 的 2 倍吞吐上。两类收益不会同时满额兑现，取决于该层实际落在哪条曲线上。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-4\">四 · 不适用与反例：outlier 与 scale 开销</h3>\n<p>4-bit 激活量化对 outlier 敏感。若 per-token 或 per-block scale 校准不当，量化误差会先污染路由打分，再导致专家选择错误——这不是精度缓慢下降，而是离散的、不可逆的路由漂移：token 被送进本不该去的专家，combine 后激活分布偏移，逐层放大。权重离线校准与运行时激活分布不一致时，NVFP4 量化误差累积到 combine 后激活，同样逐层放大影响输出质量。这类失败在离线评测中往往被平均困惑度掩盖，只有在线流量分布偏移时才暴露。</p>\n<p>另一条反例来自 scale 开销。反量化 scale 引入额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略，吞吐收益被抵消。极端情况下，batch 小到 MMA 利用率不足、scale 处理成为主耗时，NVFP4 的端到端表现可能不如 FP8——此时带宽节省没有转化为时延节省，因为瓶颈已经转移到反量化路径上。判断是否适用，要看该服务的 decode 批大小是否足以摊薄 scale 开销，以及激活分布是否存在显著 outlier 需要更细的 scale 粒度。</p>\n<ul>\n<li>适用：decode 为主、专家权重读取构成带宽瓶颈、激活分布相对温和、批大小足以摊薄 scale 开销。</li>\n<li>不适用：预填算力受限为主、KV cache 显存受限为主、激活 outlier 严重且校准数据与线上分布不一致、小 batch 且 scale 开销主导。</li>\n<li>正交项：路由容量因子、令牌丢弃、专家选择策略、分页 KV 与专家权重共存显存——这些问题的解法不在量化维度上。</li>\n</ul>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-5\">五 · 工程判断：先定位瓶颈再决定是否上 4-bit</h3>\n<p>上线前的判断顺序应当是：先用 profiler 确认 decode 阶段的时间花在专家权重读取还是 MMA 上。若读取占主导，NVFP4 的带宽减半直接对应时延改善；若 MMA 占主导，收益来自 FP4 MMA 的 2 倍吞吐，但需确认分组 GEMM 的规模足以喂满 tcgen05。两条路径都要求硬件档位支持 tcgen05 FP4 MMA，不支持该指令的卡上跑 NVFP4 只会得到“权重变小但计算没变快”的半收益。并行拓扑材料未给出具体型号，部署时需按实际互联确认 All-to-All 的 4-bit 传输路径是否真正减半，而不是在某个中转环节被重新展开成高精度。</p>\n<p>精度侧的上线门槛不是平均困惑度小于 1%，而是路由一致性：用线上流量采样做校准，对比量化前后每个 token 的专家选择是否漂移，漂移率高的层退回 FP8 或加细 scale 粒度。KV cache 保持 FP8/BF16 不动，意味着显存预算的节省只来自专家权重，容量规划时要按这个口径重算，不能把 KV 的账算进量化收益里。规模上限受 outlier 敏感性与 scale 开销约束，材料未给出具体专家数上限——这意味着专家数扩张时，必须重新验证激活 outlier 分布与 scale 开销占比，而不是沿用上一规模的校准结论。</p>\n<p>最后落在机制上：NVFP4 的收益本质是把“每 token 读全部激活专家权重”这条带宽账单打五折，同时用 16 元素共享 FP8 scale 把量化误差锁在块内。它成立的前提是瓶颈确实在这条账单上、scale 开销能被批大小摊薄、路由不因量化而漂移。三者任一不成立，收益就会被反量化 kernel 的寄存器压力或专家选择错误吃掉——这正是开头那次尾延迟失控事故里，扩容没有解决问题、换格式才解决问题的分界线。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-6\">六 · 一次路由漂移引发的尾时延雪崩：NVFP4 的边界在哪里</h3>\n<p>某在线 MoE 服务在把专家权重从 FP8 切到 NVFP4 之后，吞吐曲线看上去很漂亮，但 P99 尾时延反而恶化，并且出现了一批回答质量明显下滑的请求。复盘时定位到两个彼此耦合的失效点。其一是激活侧的量化校准：运行时激活按 token 分组量化到 NVFP4，块内共享一个 FP8 scale，而 4-bit 的 E2M1 只有极窄的动态范围，一旦某个 token 在少数通道上出现 outlier，该 16 元素块的 scale 会被这个 outlier 顶到上限，块内其余元素被压到接近零的量化格点上。其二是这个误差并不停留在 GEMM 内部——MoE 的路由打分本身也是在这些激活上算出来的，量化误差直接改变了 top-k 专家的排序，于是 token 被送进了本不该去的专家，combine 之后的激活分布进一步偏移，逐层放大。工程上这表现为：平均 tokens/s 上升，但尾时延因为专家负载倾斜而变长，同时输出质量出现不可解释的抖动。这个事故说明 NVFP4 不是一次“把位宽改小”的等价替换，它把量化误差从数值域搬进了路由决策域。</p>\n<p>要判断一个负载是否落在 NVFP4 的适用边界内，先要把它的收益来源写清楚。decode 阶段每 token 需要读取全部激活专家的权重，专家权重占显存主体，所以这一步是显存带宽受限而非算力受限的。FP8 已经把权重压到 1 字节，NVFP4 把权重与激活同时压到 4-bit，All-to-All 传输的 4-bit 权重索引与激活带宽相比 FP8 减半，专家权重读取时间近似减半，这是 tokens/s 提升的直接来源；另一半收益来自 tcgen05 原生 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍。两个收益都成立的前提是：瓶颈确实在带宽与 MMA 吞吐上，且 scale 相关的额外开销可以被摊薄。反量化在累加前按块内 scale 执行，累加器保持 FP32，公式上表现为</p>\n<div class=\"formula\">$$w_{i}=\\text{FP4}\\left(\\frac{w_i}{s_b}\\right),\\quad s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}},\\quad \\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</div>\n<p>这里的 <span>s_b</span> 是每 16 元素块共享的 FP8 scale，它既是精度的载体，也是运行时开销的载体：每个块都要在 MMA 之后做一次 scale 乘法，反量化 scale 引入额外 kernel 与寄存器压力。小 batch decode 时，单次 GEMM 的算术强度本来就低，这部分固定开销占比不可忽略，吞吐收益可能被抵消——这正是 NVFP4 在低并发、短序列场景下不划算的原因，也是它与连续批处理、批调度策略必须联合调优的原因（批调度本身见本书批调度条目，此处不展开）。</p>\n<p>失效条件可以归成三类，工程上应当逐条设卡。第一类是 outlier 敏感性：4-bit 激活量化对 outlier 敏感，必须 per-token 或 per-block scale，校准不当会导致路由打分漂移、专家选择错误；对策是把路由打分的计算路径与量化路径解耦，或在路由前保留一份 BF16/FP8 的激活副本，代价是额外的显存与一次拷贝带宽。第二类是校准分布漂移：权重是离线按 16 元素块计算 FP8 scale 并舍入到 E2M1 的，而运行时激活分布随流量变化，两者不一致时 NVFP4 量化误差会累积到 combine 后激活并逐层放大，因此离线校准集必须覆盖真实流量的长尾，且需要在线监控逐层激活的量化残差。第三类是规模与拓扑约束：硬件档位需支持 tcgen05 FP4 MMA，不具备该指令的卡上这条路径直接不成立；KV cache 仍保持 FP8/BF16，不随权重一起降到 4-bit，所以显存节省只发生在专家权重侧，长上下文场景的 KV 显存压力并不会因 NVFP4 缓解。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>NVFP4 是否适用</th><th>主要代价</th></tr></thead><tbody><tr><td>大 batch decode、带宽受限、专家权重占显存主体</td><td>适用，收益主要来自权重读取时间近似减半</td><td>scale 反量化 kernel 与寄存器压力</td></tr><tr><td>小 batch、短序列 decode</td><td>不划算，scale 开销占比不可忽略</td><td>吞吐收益被固定开销抵消</td></tr><tr><td>激活 outlier 密集、路由对扰动敏感</td><td>需 per-token/per-block scale 并解耦路由路径</td><td>额外副本显存、监控成本</td></tr><tr><td>长上下文、KV cache 主导显存</td><td>收益有限，KV 仍为 FP8/BF16</td><td>显存瓶颈未转移</td></tr></tbody></table>\n<p>还有一条容易被忽略的边界：NVFP4 与容量因子、专家选择等路由算法是正交的，它只作用于量化维度，不改变专家数量与路由策略本身。这意味着当系统因为专家负载倾斜而出现尾时延时，把权重降到 4-bit 不会修复倾斜，反而可能因为路由打分漂移而加剧倾斜。判断是否该上 NVFP4，应当先确认瓶颈确实落在专家权重读取带宽与分组 GEMM 吞吐上，再确认激活分布足够稳定、校准集覆盖长尾，最后确认部署硬件具备 tcgen05 FP4 MMA 且 batch 规模足以摊薄 scale 开销；三条中任一不满足，收益就会退化为纸面数字。</p>\n<h3 id=\"alg-nvfp4-moe-quant-sec-7\">七 · 离线校准：专家权重的块级 scale 落盘</h3>\n<p>NVFP4 的第一步不在运行时，而在权重落盘之前。对每个专家（expert）的每一张权重矩阵，按最后一维切成 16 元素的块，逐块求块内绝对值最大值，除以 FP8 可表示的最大值得到该块共享的 FP8 scale，再把块内每个元素舍入到 E2M1 网格上。写成式子就是 <span class=\"formula\">$$w_{i}=\\text{FP4}\\left(\\frac{w_i}{s_b}\\right),\\quad s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}}$$</span> 这一步的输入是 BF16/FP8 的专家权重，输出是两块东西：4-bit 的 E2M1 权重本体，以及每 16 元素一个的 FP8 scale 数组。注意 scale 的粒度是 16 而不是 128 或 256，这是 NVFP4 与 MXFP4 类格式的关键差别——块越小，块内动态范围越窄，E2M1 只有 1 位符号、2 位指数、1 位尾数，能表示的绝对值档位极少，只有把块压到 16 个元素，块内数值分布才够集中，舍入误差才压得住。</p>\n<p>这一步的代价全部落在离线侧，不占推理时延，但占显存与加载带宽。以单个专家矩阵为例，权重本体是 4 bit/元素，scale 是 8 bit/16 元素，即 0.5 bit/元素的额外开销，合计约 4.5 bit/元素，相比 FP8 的 8 bit/元素，专家权重常驻显存降到约 56%。对 MoE 这种专家权重占显存主体的负载，这个比例直接决定单卡能装下多少专家、能开多大容量因子。工程上要盯的是校准数据的代表性：校准集若只覆盖短序列，长上下文里出现的激活 outlier 在离线阶段完全不可见，权重 scale 会偏小，运行时反量化就把误差放大——这是后文失败模式的根。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-8\">八 · 激活侧量化：per-token 分组与 scale 随行</h3>\n<p>请求进入 decode 循环后，每一层在进入 MoE 之前要先做激活量化。输入是这一层 hidden state 的 BF16 激活，按 token 分组、组内再按 16 元素切块，逐块算 scale 并舍入：<span class=\"formula\">$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$</span> 输出是 4-bit 激活本体加上随 token 走的 FP8 scale 数组。与权重不同，激活的分布每个 token 都不一样，scale 必须在运行时现算，因此这一步是一个独立的量化 kernel，输入输出都在片上或近端显存，代价是每个 token 每个被路由到的专家都要跑一遍。</p>\n<p>关键在于 scale 的“随行”语义：scale 不是留在原地的元数据，而是要和 4-bit 激活一起被打包进 dispatch 缓冲，跟着 token 被 All-to-All 送到目标专家所在的设备。这意味着 dispatch 缓冲的布局必须是“4-bit 数据 + FP8 scale 交错或分段”，接收端才能在不回读原设备的情况下完成反量化。代价体现在两处：一是量化 kernel 本身的启动与寄存器开销，小 batch decode 时每 token 的计算量很小，kernel launch 与 scale 计算的固定开销占比被放大；二是缓冲打包带来的额外写带宽，虽然 4-bit 本体减半，但 scale 的 0.5 bit/元素让有效载荷变成 4.5 bit，收益不是纯粹的 2 倍。</p>\n<p>具体例子：一个 batch 里 8 个 token 被路由到同一专家的同一分组 GEMM，若按 per-token 量化，这 8 个 token 各自带一套 scale，接收端要按 token 维度做 8 次不同的块内反量化；若改成 per-block 跨 token 共享 scale，scale 数量降下来、反量化循环更整齐，但对 outlier 的容忍度变差。这个取舍就是下一节 GEMM 里 scale 应用方式的分水岭。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-9\">九 · All-to-All：4-bit 载荷与索引的带宽账</h3>\n<p>dispatch 阶段，token 的 4-bit 激活与 scale 被打包，连同目标专家索引一起进入 All-to-All。输入是本卡量化后的激活块与路由表，输出是各目标 rank 上按专家聚合的激活缓冲。带宽账很直接：FP8 时每元素 1 字节，NVFP4 时本体 0.5 字节加 scale 摊薄后的 0.0625 字节，约 0.5625 字节/元素，相对 FP8 减半略多。但“减半”只对本体的有效载荷成立，实际链路还要传索引、偏移、计数这些控制面数据，它们不随量化位宽缩小，因此小消息、多专家的碎片化传输里，控制面占比上升，端到端带宽收益会低于 2 倍。</p>\n<p>这一步的系统代价是尾时延而非均值：All-to-All 是同步点，最慢的那条链路决定整个 MoE 层的完成时间。专家并行度越高，单条消息越小，4-bit 载荷的收益越容易被固定开销吃掉。工程判断是：NVFP4 的带宽红利在专家并行度适中、单专家批量足够大的拓扑上兑现得最充分；一旦切到细粒度专家并行，就要靠合并消息、按专家聚合后再发来摊薄控制面。传输完成后接收端拿到的是 4-bit 激活与 FP8 scale，两者必须保持可配对的布局，否则反量化 kernel 要做一次额外的重排，等于把省下的带宽又还回去。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-10\">十 · tcgen05 FP4 MMA：分组 GEMM 与累加前反量化</h3>\n<p>专家侧拿到 4-bit 权重与 4-bit 激活后，走 tcgen05 的 FP4 MMA 路径。输入是两块 E2M1 矩阵与各自的 FP8 scale 数组，输出是 FP32 累加器里的部分和。计算本身是 <span class=\"formula\">$$\\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</span> 即先在块内做 4-bit 整数乘加，再在跨块累加时把两个 scale 的乘积乘回去。tcgen05 原生支持 FP4 MMA，同样指令周期内处理的元素数是 FP8 的两倍，分组 GEMM 的吞吐上限因此抬到 FP8 的 2 倍——这是纸面上限，实际能否吃到取决于 scale 反量化的插入位置是否挡住了 MMA 流水。</p>\n<p>反量化的位置是这一步最要紧的工程决策。若在 MMA 之后、写回累加器之前逐块乘 scale，scale 乘法落在 FP32 累加路径上，每 16 个元素的点积结果配一次乘法，寄存器压力集中在累加器一侧；若把 scale 预先折叠进权重侧（离线把 <span class=\"formula\">$$s_b^{w}$$</span> 吸收到激活 scale 里），运行时只需一次乘法，但要求权重与激活的块边界严格对齐，且激活 scale 要在 dispatch 前就与目标专家的权重 scale 配对，跨设备场景下做不到。多数实现选择前者，代价是反量化 kernel 与 MMA 之间的同步开销，以及 FP32 累加器占用带来的寄存器与 TMEM 压力。</p>\n<p>系统代价在这里最直观：decode 阶段每 token 要读全部激活专家的权重，权重读取时间近似减半，直接抬升 tokens/s；但小 batch 时 MMA 的算术强度低，瓶颈仍在权重读取，此时 4-bit 的收益最大，而 scale 反量化的固定开销也最扎眼。batch 增大后算术强度上升，FP4 MMA 的 2 倍吞吐才开始兑现，反量化开销被摊薄。这就是为什么 NVFP4 的收益曲线随 batch 变化不是单调的。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-11\">十一 · combine 与回写：反量化回 BF16、KV cache 不动</h3>\n<p>专家计算完成后进入 combine：各专家的 FP32 部分和按路由权重加权求和，输出反量化回 BF16 进入下一层。输入是 FP32 累加结果与路由权重，输出是 BF16 的 hidden state。这一步的代价是每个 token 一次反量化写回，量不大但处在关键路径上，与下一层的量化 kernel 首尾相接，两者之间的融合能省一次显存往返。要注意 KV cache 在这一整套流程里保持 FP8/BF16 不变——NVFP4 只作用于专家权重与 MoE 路径上的激活，注意力侧的 KV 不走 4-bit，因此显存节省只发生在专家权重这一块，容量规划时不能把 KV 的账算进 NVFP4 的收益里。</p>\n<p>失败模式在这一步显形：权重离线校准与运行时激活分布不一致时，块内量化误差不会被抵消，而是随 combine 加权逐层累积，逐层放大后影响输出质量。4-bit 激活对 outlier 尤其敏感，一个 token 里少数几个大幅值元素若落在块边界上，会把整块的 scale 拉高，块内其余元素被压到 E2M1 的低档位，有效精度骤降；这种误差经路由打分回传，可能让本应选中的专家落选，形成路由打分漂移与专家选择错误的连锁。稳定性技巧是 per-token 或 per-block scale 的校准要覆盖长尾激活，并在 combine 前保留 FP32 累加以避免二次舍入。</p>\n<p>工程判断落在最后这一段：NVFP4 的收益不是“位宽减半即吞吐翻倍”的线性关系，而是由权重读取时间、scale 反量化开销、All-to-All 控制面占比三者共同决定的曲线。小 batch decode 时权重读取主导，收益最实在，但 scale 开销占比最高；大 batch 时 FP4 MMA 吞吐兑现，反量化被摊薄，收益转向算力侧。部署前要按目标 SLO 的 tokens/s 与尾时延，在这条曲线上找 batch 与专家并行度的交点，而不是默认 4-bit 一定比 FP8 快。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-12\">十二 · 量化流水线的断点：从校准到 combine 的失效面</h3>\n<p>把 NVFP4 拆成按请求流动的步骤看，每一环都有明确的输入输出与代价，而失效点恰恰落在环与环的衔接处。离线校准阶段，输入是每个专家的 BF16 权重，按 16 元素块求 <span class=\"formula\">$$s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}}$$</span> 并把块内元素舍入到 E2M1，输出是 4-bit 权重索引加一份与权重同寿命的 FP8 scale 表。代价在显存：权重主体从 FP8 的 1 字节降到 0.5 字节，但每 16 元素附带 1 字节 scale，等效位宽变成 4.5 bit，压缩率只有约 1.78 倍而非名义上的 2 倍——scale 表的粒度越细，这笔固定开销占比越高。更关键的是这一步是离线的，它冻结了权重分布假设；一旦运行时某专家的激活分布偏离校准集，块内最大值撑不住 outlier，舍入误差就会在后续所有 token 上复现。</p>\n<p>运行时第一步是激活量化：输入是 dispatch 前的 BF16 激活，按 token 分组、组内再按 16 元素块求 scale，输出 4-bit 激活与随 token 同行的 scale，写入 dispatch 缓冲。这里的系统代价是额外一个量化 kernel 的启动与寄存器占用，在 decode 小 batch 场景下每 token 的 MMA 工作量本就有限，这个 kernel 的固定开销无法被摊薄，直接吃掉一部分带宽收益。失效条件很明确：per-token 单 scale 在激活存在通道级 outlier 时会整体压缩动态范围，per-block 则让 scale 数量随 token 长度线性增长，两者都要在精度与缓冲体积之间取舍；校准不当的后果不是数值噪声，而是路由打分漂移——门控网络吃到失真的激活，选错专家，错误在 combine 后被放大。</p>\n<p>传输与计算环节：All-to-All 搬运 4-bit 索引与激活，带宽相对 FP8 减半，这是收益最确定的一环；tcgen05 上 FP4 MMA 执行分组 GEMM，FP32 累加器在块内按 <span class=\"formula\">$$\\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</span> 反量化，吞吐可达 FP8 的 2 倍。代价是反量化不能免费：scale 乘法插在累加路径上，要求 MMA 输出与 scale 表在寄存器或 TMEM 中保持可索引的对齐，块数越多索引压力越大。最后 combine 把激活反量化回 BF16 进入下一层，KV cache 维持 FP8/BF16 不动——这意味着 NVFP4 的收益只覆盖权重与激活通路，注意力侧的带宽账单没有变化，端到端加速比因此被 KV 读取稀释。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>离线校准</td><td>BF16 权重→E2M1+FP8 scale</td><td>等效 4.5 bit，压缩率约 1.78×</td><td>校准分布与运行时激活不一致</td></tr><tr><td>激活量化</td><td>BF16 激活→NVFP4+scale</td><td>额外 kernel、寄存器压力</td><td>outlier 致路由打分漂移</td></tr><tr><td>All-to-All</td><td>4-bit 索引/激活→远端专家</td><td>带宽减半，收益确定</td><td>小消息主导时延迟不降</td></tr><tr><td>FP4 MMA</td><td>分组 GEMM→FP32 累加</td><td>scale 索引与反量化开销</td><td>块数过多致索引瓶颈</td></tr><tr><td>combine</td><td>累加结果→BF16</td><td>逐层误差累积</td><td>量化误差放大影响输出</td></tr></tbody></table>\n<p>工程判断落在规模上限上：这套方案的上限不由专家数决定，而由 outlier 敏感性与 scale 开销的比值决定。当 batch 足够大、MMA 工作量能摊薄量化与反量化 kernel 时，4-bit 通路的收益接近理论值；当 batch 收缩到 decode 尾段、每 token 只触发少量专家时，scale 的固定成本占比上升，吞吐收益被抵消，此时应回退到 FP8 权重配 BF16 激活的保守组合，把 NVFP4 留给预填阶段或大 batch 稳态。逐层误差累积则要求校准集覆盖长尾激活分布，否则 combine 后的偏差会在深层被放大到不可接受。</p>\n<h3 id=\"alg-nvfp4-moe-quant-sec-13\">十三 · 公式三项：块内归一、E2M1 舍入、双 scale 还原</h3>\n<p>NVFP4 的核心公式写成一行是 <span class=\"formula\">$$w_{i}=\\text{FP4}\\left(\\frac{w_i}{s_b}\\right),\\quad s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}},\\quad \\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</span>。三项各自对应一个不可省略的工程动作，逐项拆开看。</p>\n<p>第一项是块内归一：把块内每个元素除以该块共享的 scale，得到落在 E2M1 可表示区间内的浮点商。这一步不是“顺便缩放”，它决定了 E2M1 的四个指数位与一个尾数位能覆盖的动态范围。E2M1 只有 1 位尾数，可表示值稀疏（0、±0.5、±1、±1.5、±2、±3、±4、±6 这一档量级），归一后商必须落进这个格点集合，否则舍入误差立刻放大。块宽取 16 是硬约束：tcgen05 的 FP4 MMA 在 K 维上按块消费 scale，块宽与 MMA 的 scale 广播粒度对齐，才能让 scale 在 tensor core 内部而不是在寄存器里被乘进去。</p>\n<p>第二项是 scale 的定标：<span class=\"formula\">$$s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}}$$</span>，分子是块内绝对值最大元素，分母是 FP8 可表示的最大值。这一步的推导关键在“为什么除的是 FP8_max 而不是 E2M1_max”。因为 scale 本身以 FP8 存储，它必须能被 FP8 精确表示且不溢出；用块内最大值除以 FP8_max，等价于把块内最大元素映射到 FP8 满量程，商再被 E2M1 舍入时，最大元素恰好落在 E2M1 的最大可表示值附近，块内其余元素按比例缩下去。若改用 E2M1_max 作分母，scale 会偏大，块内小元素被压到 0 附近，尾数位本来就少，直接丢精度。这是整条推导里最关键的一步：scale 的定标基准由 scale 自身的存储格式决定，不由被量化数据的格式决定。</p>\n<p>第三项是双 scale 还原：<span class=\"formula\">$$\\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</span>。注意求和顺序——先做块内 FP4 点积得到整数/定点累加，再乘两个 scale 后跨块求和。这个顺序把 scale 乘法从“每元素一次”降为“每块一次”，是 NVFP4 能在 tcgen05 上跑出吞吐的前提。代价是累加器必须足够宽：块内点积在 FP32 累加器里做，跨块乘 scale 后再进 FP32 累加，否则 16 个 4-bit 乘积的中间和会溢出或被截断。工程上这意味着 TMEM 里的累加器按 FP32 布局，而不是按 FP16 省一半空间。</p>\n<p>具体例子：某专家某 16 元素块内最大权重绝对值为 0.9，FP8_max 取该格式满量程，则 <span class=\"formula\">$$s_b=0.9/\\text{FP8}_{\\max}$$</span>，块内 0.9 归一后接近 1，落在 E2M1 的 1.0 格点上；块内 0.05 的元素归一后约为 0.055，被舍入到 0 或 0.5 档中最接近者，误差由该块 scale 在还原时按比例带回。这就是“微缩放”名字的来历：误差被限制在 16 元素窗口内，不跨块传播。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-14\">十四 · 激活侧的对称推导与 per-token 分组</h3>\n<p>激活量化用同一套公式的镜像：<span class=\"formula\">$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$</span>。形式上与权重侧完全对称，但工程含义不同：权重是离线校准、一次定终身；激活是运行时逐 token 产生，scale 必须跟着 token 走。</p>\n<p>推导的关键一步在“分组维度选谁”。权重按输出通道的连续 16 元素分块，因为权重布局在离线时就固定，块边界可以按 MMA 的 K 维切；激活则按 token 分组，同一 token 的 16 个连续特征共享一个 scale。这样做的理由是激活的 outlier 集中在少数通道上，per-token scale 能把整 token 的动态范围压进 E2M1，而 per-block（跨 token）scale 会让 outlier token 拉高整块 scale、压低同块正常 token 的有效位数。代价是 scale 的数量等于 token 数乘以特征维除以 16，这些 scale 要随 token 一起进入 dispatch 缓冲，在 All-to-All 里多传一份 FP8 数据——相对 4-bit 激活本体，scale 的字节占比是 1/4 量级（每 16 个 4-bit 元素配 1 个 8-bit scale），这是 NVFP4 相对纯 4-bit 格式必须付的带宽税。</p>\n<p>还原时的对称性体现在 combine 阶段：<span class=\"formula\">$$\\hat{y}=\\sum_b s_b^{w}s_b^{x}\\sum_{i\\in b}\\hat{w}_i\\hat{x}_i$$</span> 里两个 scale 相乘，权重 scale 是离线常量、激活 scale 是运行时变量，乘法的结合顺序影响寄存器压力。实现上把 <span class=\"formula\">$$s_b^{w}$$</span> 预先折叠进权重侧的块描述符，运行时只做一次 <span class=\"formula\">$$s_b^{x}$$</span> 乘法，可省掉一半的 scale 读取。这是“反量化 scale 引入额外 kernel 与寄存器压力”这条代价的直接来源：折叠做得好，scale 开销藏在 MMA 的流水里；折叠做不好，每块一次标量乘法就把小 batch decode 的 SM 占用吃掉。</p>\n<p>具体例子：decode 阶段一个 token 的激活向量进入某专家，按 16 元素切块后每块算一个 FP8 scale，scale 与 4-bit 量化值一起写入 dispatch 缓冲；All-to-All 把这批数据送到目标专家的 GPU 上，接收端按块描述符取 <span class=\"formula\">$$s_b^{x}$$</span>，与预折叠的 <span class=\"formula\">$$s_b^{w}$$</span> 相乘后进 FP32 累加。整条链路上没有任何一步需要把 4-bit 激活展开回 BF16——展开只发生在 combine 之后、进下一层之前。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-15\">十五 · 伪代码：从校准到分组 GEMM 的可实现骨架</h3>\n<p>把公式落到可实现，需要三段伪代码：离线校准、运行时量化、分组 GEMM 内核。三段之间的接口是块描述符（4-bit 数据 + FP8 scale），不是原始浮点。</p>\n<ul>\n<li>离线校准（每专家一次）：对权重矩阵按 K 维每 16 元素切块，逐块求 <span class=\"formula\">$$\\max_{j\\in b}|w_j|$$</span>，除以 FP8_max 得 <span class=\"formula\">$$s_b^{w}$$</span>，把 <span class=\"formula\">$$w_i/s_b^{w}$$</span> 舍入到 E2M1，打包成 4-bit 索引与 FP8 scale 两张表。校准的产物是只读的，随专家权重一起常驻显存。</li>\n<li>运行时量化（每 token 每层）：对激活向量按 token 内 16 元素切块，求块内最大值定 <span class=\"formula\">$$s_b^{x}$$</span>，舍入到 E2M1，把 4-bit 值与 FP8 scale 写入 dispatch 缓冲的连续槽位，scale 与数据同槽便于 All-to-All 一次搬走。</li>\n<li>分组 GEMM（tcgen05）：按 token 到专家的路由结果把行分组，每组以 FP4 MMA 指令消费权重块与激活块，块内点积进 FP32 累加器，跨块乘 <span class=\"formula\">$$s_b^{w}s_b^{x}$$</span> 后继续累加，输出写回 BF16 供 combine 使用。</li>\n</ul>\n<p>伪代码层面最容易被忽略的是块描述符的对齐。tcgen05 的 FP4 MMA 要求 scale 在 K 维上按固定步长广播，若权重块与激活块的块边界不对齐（例如激活按 token 切、权重按通道切，两者在 K 维上的块起点错位），内核就得在寄存器里重排块边界，这一步的 shuffle 开销在小 batch 下会盖过 MMA 本身的收益。可实现的写法是：离线校准时就把权重块边界固定成与 MMA K 步长一致的网格，运行时激活量化强制按同一网格切块，两边块号一一对应，内核里只做块号索引、不做重排。</p>\n<p>系统代价落在这里：分组 GEMM 的吞吐可达 FP8 的 2 倍，但这是 MMA 指令层面的上限；端到端 tokens/s 取决于专家权重读取时间是否真的近似减半。权重与激活带宽相比 FP8 减半，decode 阶段每 token 读全部激活专家权重的字节数减半，读取时间近似减半——这是收益的主项。代价项是 scale 的额外 kernel 与寄存器压力，在小 batch decode 时占比不可忽略，收益会被抵消一部分。判断一个实现是否划算，看的是“减半的权重读取时间”减去“scale 处理时间”后的净值，而不是 MMA 峰值。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-16\">十六 · 精度推导：误差如何在块内被约束、在层间被放大</h3>\n<p>NVFP4 的误差分析可以按块做局部化推导。块内每个元素的量化误差上界由 E2M1 的格点间距决定，归一后商落在 <span class=\"formula\">$$[0,1]$$</span> 区间（按块内最大值归一），E2M1 在该区间的格点间距不均匀，靠近 0 处密、靠近 1 处疏，因此块内小元素的相对误差大、大元素的相对误差小。还原时乘回 <span class=\"formula\">$$s_b$$</span>，绝对误差被 scale 同比缩放，块内误差不会跨块传播——这是微缩放相对 per-tensor 量化的本质优势：一个 outlier 块不会污染整层。</p>\n<p>但误差会在层间放大，路径是 combine 后的激活。权重离线校准的分布与运行时激活分布不一致时，NVFP4 量化误差累积到 combine 后激活，逐层放大影响输出质量。推导上的关键量是每层的量化噪声功率与信号功率之比，噪声在残差连接里被累加、在归一化里被部分抑制，最终体现在困惑度上。材料给出的定性结论是微缩放精度损失在 MoE 上通常小于 1% 困惑度，这个量级说明块内约束足够紧，前提是校准分布覆盖运行时分布。</p>\n<p>更隐蔽的一条路径是路由打分漂移。MoE 的路由打分由激活与路由权重算得，若激活被 4-bit 量化后再参与打分（或打分用的激活与 GEMM 用的激活同源），量化噪声会改变 top-k 专家选择。4-bit 激活量化对 outlier 敏感，per-token 或 per-block scale 校准不当会导致路由打分漂移、专家选择错误——选错专家不是精度问题，是计算路径问题，错误会被后续层完整继承。工程上的防御是把路由打分放在量化之前、用 BF16 算，只让 GEMM 消费量化后的激活；代价是多一份未量化的激活副本，显存带宽上要单独核算。</p>\n<p>具体例子：某层某 token 的激活在 16 元素块内有一个幅值远超同块其余元素的 outlier，per-token scale 由该 outlier 定标，同块其余元素归一后落在 E2M1 的低格点区，有效位数进一步减少；若该块恰好参与路由打分，打分向量被压低，top-k 选择偏移。把打分与 GEMM 的激活解耦，或对打分路径单独保留高精度副本，是这条失败模式的直接对策。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-17\">十七 · 与 KV cache、combine 的边界：哪些张量不进 NVFP4</h3>\n<p>公式的适用范围有明确边界：NVFP4 只覆盖专家权重与进入分组 GEMM 的激活，KV cache 仍保持 FP8/BF16。这不是实现偷懒，而是推导上的必然。KV cache 在 decode 阶段被反复读取、跨 token 复用，其误差会随序列长度累积；4-bit 的 E2M1 在长上下文下对 attention 分数的扰动不可控，且 KV cache 的访问模式是分页的、与分组 GEMM 的块结构不匹配，scale 无法按 16 元素块对齐到分页粒度。把 KV cache 留在 FP8/BF16，等于把量化误差的累积路径切断在 attention 之前。</p>\n<p>combine 之后激活反量化回 BF16 进入下一层，这一步是精度恢复点。分组 GEMM 的输出在 FP32 累加器里，乘完双 scale 后仍是浮点，写回时降到 BF16 供下一层消费；下一层若还是 MoE，激活会再次被量化到 NVFP4，形成“量化—GEMM—反量化—再量化”的循环。每一轮循环的误差由块内约束兜住，但循环次数等于 MoE 层数，层数越多、累积噪声越大。这就是为什么校准要覆盖整条链路而不只是单层：离线校准只对权重做，运行时激活的分布漂移无法被离线捕获，只能靠 per-token scale 在运行时自适应。</p>\n<p>系统代价在这一节体现为显存账：专家权重压到 4-bit 后，权重占用的显存减半，省下的空间可以留给 KV cache 或更大的批；但 scale 表本身占显存（每 16 元素一个 FP8），块越细 scale 表越大，块宽 16 是带宽与精度的折中点。KV cache 保持 FP8/BF16 意味着它不参与这次减半，decode 阶段的显存带宽账单里，KV cache 读取与专家权重读取是两项独立开销，NVFP4 只砍后者。容量规划时必须把这两项分开算，不能把“权重减半”直接外推成“总带宽减半”。</p>\n<p>具体例子：一个 MoE 层在 decode 时读若干激活专家的 4-bit 权重与对应 scale 表，同时读该 token 的 KV cache（FP8/BF16）；前者字节数相比 FP8 权重减半，后者不变。若 KV cache 读取在总带宽里占比高，NVFP4 的端到端收益就被稀释——这正是“规模上限受 outlier 敏感性与 scale 开销约束”之外的另一条隐性上限：收益上限由权重读取在总带宽中的占比决定。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-18\">十八 · 工程判断：什么条件下这套公式值得落地</h3>\n<p>把公式推导收束成可执行的判断，需要三个检查点。第一，硬件档位是否支持 tcgen05 FP4 MMA——不支持则公式里的 FP4 点积只能退化成软件模拟，吞吐收益归零，只剩带宽收益。第二，专家权重读取是否真的是 decode 阶段的主带宽项——若 KV cache 或 All-to-All 传输占主导，权重减半的收益被摊薄，此时应优先优化那两项而不是量化。第三，小 batch decode 下 scale 开销占比是否可接受——反量化 scale 引入额外 kernel 与寄存器压力，batch 越小、MMA 占用越低，scale 处理的相对开销越高，净值可能为负。</p>\n<p>推导给出的量化收益上界是清晰的：权重与激活带宽相比 FP8 减半，decode 阶段专家权重读取时间近似减半，直接抬升 tokens/s；tcgen05 原生支持 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍。这两个“2 倍”不是叠加关系，前者是带宽账、后者是算力账，decode 阶段通常带宽受限，所以真正兑现的是前者；prefill 阶段算力占比上升，后者才开始起作用。把两个阶段的收益分开核算，是容量规划里最容易出错的地方。</p>\n<p>失败模式的工程对策可以写进实现约束：4-bit 激活量化对 outlier 敏感，per-token 或 per-block scale 校准不当会导致路由打分漂移、专家选择错误，因此路由打分路径保留高精度、量化只作用于 GEMM 输入；权重离线校准与运行时激活分布不一致时误差逐层放大，因此校准集要覆盖真实流量分布、并在上线后监控 combine 后激活的分布漂移；scale 开销在小 batch 下不可忽略，因此内核要把 <span class=\"formula\">$$s_b^{w}$$</span> 预折叠进块描述符、只留一次 <span class=\"formula\">$$s_b^{x}$$</span> 乘法，并把 scale 读取与 MMA 流水重叠。</p>\n<p>最后一个判断落在块宽上。每 16 元素共享 FP8 scale 是公式里的固定参数，不是可调超参：块宽变宽，scale 表变小、带宽税变轻，但块内动态范围变大、E2M1 的有效位数被 outlier 吃掉；块宽变窄，精度变好、scale 表变大、All-to-All 里 scale 的字节占比上升。16 这个值同时对齐了 tcgen05 的 scale 广播粒度与 FP8 scale 的存储粒度，改动它就要同时改内核的块描述符布局与 dispatch 缓冲的槽位排布——这是公式与实现之间最硬的一条耦合，也是落地前必须先验证的一条。</p>\n<h3 id=\"alg-nvfp4-moe-quant-sec-19\">十九 · 请求形态：NVFP4 的收益只在“专家权重主导”的形态里成立</h3>\n<p>NVFP4 微缩放量化的收益结构非常明确：它把专家权重与激活都压到 4-bit，使 decode 阶段每 token 读取激活专家权重的字节数相比 FP8 减半。因此，负载配方第一条判据是“单次前向里，专家权重读取量是否主导总字节数”。当请求形态是长上下文、单条或极小并发的 decode，每 token 需要遍历的激活专家集合固定，权重读取量随专家数线性增长，而激活读取量只与 hidden 维度相关，权重项占绝对多数，此时 NVFP4 的带宽收益接近理论上限。反过来，当请求形态是短 prompt、大并发、以预填为主，计算从带宽受限转向 MMA 吞吐受限，激活量随 batch 线性放大，权重读取被摊薄，NVFP4 的边际收益就被预填的算力需求盖过。工程判断上，把 NVFP4 的部署档位绑定到“decode 主导、专家权重常驻显存”的服务面上，而不是全流量无差别开启。</p>\n<p>代价侧同样由形态决定。反量化 scale 需要额外 kernel 与寄存器压力，在小 batch decode 时 scale 开销占比不可忽略，吞吐收益会被抵消。也就是说，请求形态越接近“单 token、小 batch”，权重带宽收益越大，但 scale 开销的相对占比也越高，两者在同一个区间里反向拉扯。存在一个由硬件 FP4 MMA 吞吐、scale 反量化指令开销、每 token 激活专家数共同决定的批大小区间：低于它，scale 开销吃掉收益；高于它，权重读取被 batch 摊薄、收益变薄。材料未给出具体批大小数值，配方只能定性给出这个区间的存在性与判断方法——用 profiler 分别测 FP4 MMA 时间与 scale 反量化时间，看后者占比是否超过前者节省下来的权重读取时间。</p>\n<div class=\"formula\">$$T_{\\text{decode}} \\approx \\underbrace{\\frac{B_w \\cdot E_{\\text{act}}}{BW_{\\text{HBM}}}}_{\\text{权重读取}} + \\underbrace{\\frac{B_a \\cdot E_{\\text{act}}}{BW_{\\text{HBM}}}}_{\\text{激活读取}} + \\underbrace{T_{\\text{scale}}(N_{\\text{blk}})}_{\\text{反量化开销}}$$</div>\n<p>其中 $B_w$ 为每专家权重字节数（NVFP4 下为 FP8 的一半），$E_{\\text{act}}$ 为每 token 激活专家数，$B_a$ 为激活字节数，$N_{\\text{blk}}$ 为 16 元素块数。NVFP4 只压缩前两项，第三项随块数增长而增长，且不随 batch 摊薄——这正是小 batch 下收益被抵消的数学来源。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-20\">二十 · 长度分布：长上下文放大权重项，短上下文放大激活项</h3>\n<p>长度分布对 NVFP4 的影响通过 KV cache 与激活两条路径传导。KV cache 在本算法中保持 FP8/BF16，不参与 NVFP4 量化，因此长上下文请求的显存占用主体仍是 KV cache，NVFP4 只作用于专家权重与当层激活。这意味着：上下文越长，KV cache 占比越高，专家权重在总显存中的相对份额下降，NVFP4 带来的显存节省被稀释；但 decode 每步的权重读取量并不随上下文长度变化，所以带宽收益不受上下文长度影响，受影响的只是“显存容量账本”上的收益感知。配方上应把 NVFP4 的容量收益按“专家权重占显存比例”折算，而不是按总显存折算。</p>\n<p>短上下文、高并发的形态则是另一条路径。激活按 token 分组量化到 NVFP4，scale 随 token 一起进入 dispatch 缓冲，batch 越大，dispatch 缓冲里的激活字节越多，All-to-All 传输的激活侧带宽随之上升。虽然 NVFP4 让激活带宽相比 FP8 减半，但当激活项在 All-to-All 总字节中占比升高时，权重索引侧的减半收益被稀释。因此长度分布的配方判据是：统计 dispatch 缓冲中权重索引字节与激活字节的比例，比例偏向权重时 NVFP4 收益最大，偏向激活时收益收敛到激活减半这一项。</p>\n<p>具体例子：一个以长文档问答为主的服务面，上下文长度分布右偏，KV cache 占用高、专家权重占比低，NVFP4 的主要贡献落在 decode 带宽而非容量；而一个以短对话、高并发为主的服务面，激活侧字节占比高，NVFP4 的贡献落在 All-to-All 激活减半与 FP4 MMA 吞吐上。两者都适合 NVFP4，但收益来源不同，容量规划时不能套用同一套折算系数。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-21\">二十一 · 并发与批大小：连续批处理把 scale 开销摊薄，但也把 outlier 风险放大</h3>\n<p>连续批处理对 NVFP4 是双刃剑。批内 token 数上升，反量化 scale 的 kernel 启动与寄存器压力被更多 token 分摊，scale 开销占比下降，这是有利的一面；同时，批内 token 来自不同请求、不同层、不同专家，激活分布跨度变大，4-bit 激活量化对 outlier 敏感的问题被放大——per-token 或 per-block scale 若按批内统一校准，长尾 outlier 会把整块的 scale 拉大，块内其余元素的量化分辨率被压缩，量化误差累积到 combine 后激活，逐层放大影响输出质量。配方上要求激活量化必须按 token 或按块独立计算 scale，不能跨 token 共享，这与权重侧按 16 元素块离线校准是两套独立机制。</p>\n<p>并发上升还会改变路由打分的稳定性。路由打分依赖激活值，激活被量化到 E2M1 后，打分输入的微小扰动可能改变 top-k 专家选择。校准不当会导致路由打分漂移、专家选择错误，而专家选择错误在 MoE 里是结构性代价：选错专家意味着该 token 的输出来自不匹配的专家，且被选中的专家权重读取量不变，等于用同样的带宽换更差的输出。批越大，这种漂移在统计上越容易被平均掉，但单 token 的错误不会被平均——尾时延与质量尾部由最差的那条请求决定。</p>\n<p>配方判据：把批大小上限设在“scale 开销占比低于权重读取节省”与“路由漂移率低于可接受阈值”两条约束的交集内。前者用 profiler 测，后者用离线校准集上的路由一致率测。材料未给出具体阈值，工程上以“NVFP4 相对 FP8 的路由 top-k 一致率”作为上线门槛，一致率下降超过可容忍范围就收紧批大小或改为 per-block scale。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-22\">二十二 · 负载不对时的三种失效形态</h3>\n<p>第一种是预填主导型负载。请求以长 prompt、低 decode 步数为特征，计算由预填的分组 GEMM 吞吐决定。NVFP4 的 FP4 MMA 吞吐可达 FP8 的 2 倍，这部分收益成立；但权重读取减半的收益在预填阶段被摊薄，因为预填一次处理大量 token，权重读取被复用，带宽不再是瓶颈。此时若把 NVFP4 当作“万能加速”上线，实际观测到的端到端提升远小于 decode 场景，容量规划会高估收益。失效形态表现为：tokens/s 提升集中在预填吞吐，尾时延改善有限。</p>\n<p>第二种是小 batch decode 型负载。批大小低到 scale 反量化开销与权重读取时间同量级，NVFP4 的带宽减半被 scale kernel 吃掉，吞吐收益被抵消。这种负载在低并发、低 QPS 的服务面上常见，尤其是延迟敏感、单请求独占资源的部署。失效形态表现为：单 token 延迟不降反升，因为反量化多了一次 kernel 往返。配方上对这种负载要么合并请求抬高批大小，要么在该服务面上退回 FP8 权重路径。</p>\n<p>第三种是分布漂移型负载。权重离线校准用的是校准集分布，运行时激活分布与校准集不一致，NVFP4 量化误差累积到 combine 后激活，逐层放大影响输出质量。这种失效最隐蔽：吞吐指标正常，质量指标在长尾请求上缓慢劣化。失效形态表现为：困惑度在特定输入类别上抬升，路由 top-k 与 FP8 路径的分歧率上升。配方上要求在线监控路由一致率与输出质量抽样，把分布漂移当作与吞吐同等重要的上线门槛。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主导瓶颈</th><th>NVFP4 收益来源</th><th>失效表现</th></tr></thead><tbody><tr><td>长上下文、低并发 decode</td><td>专家权重带宽</td><td>权重读取减半</td><td>容量收益被 KV cache 稀释</td></tr><tr><td>短上下文、高并发</td><td>All-to-All 激活带宽</td><td>激活传输减半</td><td>权重索引收益被稀释</td></tr><tr><td>预填主导</td><td>分组 GEMM 吞吐</td><td>FP4 MMA 2 倍吞吐</td><td>端到端提升远小于预期</td></tr><tr><td>小 batch decode</td><td>scale 反量化开销</td><td>带宽减半</td><td>吞吐收益被抵消，延迟上升</td></tr><tr><td>分布漂移</td><td>量化误差累积</td><td>无</td><td>质量长尾劣化，路由分歧</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-23\">二十三 · 配方落地：把负载判据写进部署档位与监控项</h3>\n<p>负载配方最终要落到部署档位的选择逻辑上。硬件档位需支持 tcgen05 FP4 MMA，这是 NVFP4 路径成立的前提；不具备该能力的档位不应开启 NVFP4，否则 FP4 数据要在非原生路径上反量化回更高精度执行，带宽收益被反量化开销吃掉。并行拓扑材料未给出具体型号，但配方上要求 dispatch 缓冲的激活量化与 All-to-All 传输在同一拓扑内完成，避免跨档位传输时精度来回转换。</p>\n<p>监控项按负载形态分组：decode 主导面监控每 token 专家权重读取字节与 scale 反量化时间占比；高并发面监控 dispatch 缓冲中激活字节占比与路由 top-k 一致率；预填主导面监控 FP4 MMA 利用率与端到端 tokens/s 的分解。三项监控共同决定是否维持 NVFP4 档位，任何一项越界就触发降级到 FP8 路径。KV cache 保持 FP8/BF16 不变，因此降级只影响专家权重与激活路径，不涉及 KV 重算。</p>\n<p>具体工程判断：当一个服务面的请求长度分布右偏、并发中等、decode 步数占主导时，NVFP4 的收益结构最完整——权重读取减半直接抬升 tokens/s，scale 开销被批大小摊薄，路由漂移在中等并发下可控。反之，长度分布左偏、并发极高或极低、预填占比高的服务面，应把 NVFP4 限定在 decode 子路径上，预填仍走 FP8 或更高精度路径，避免用同一套量化配置覆盖两种瓶颈完全不同的阶段。</p>\n<p>最后落在机制上：NVFP4 的负载适配性由三个量的比值决定——每 token 激活专家权重字节、每 token 激活字节、每 16 元素块的 scale 反量化开销。前两者决定带宽收益的上限，第三者决定收益能否兑现。配方的工作就是持续测量这三个量在真实流量下的分布，把批大小与量化粒度锁在收益兑现的区间内，而不是把 NVFP4 当作与负载无关的全局开关。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-24\">二十四 · 负载配方：什么时候 NVFP4 真能兑现带宽减半</h3>\n<p>NVFP4 的收益结构决定了它只对一类负载友好：<strong>decode 主导、单 token 需激活大量专家、批大小足以摊薄 scale 开销</strong>的 MoE 服务。原因是收益项与代价项随负载形态反向变化。收益侧，每 token 读取的专家权重字节数从 FP8 的 1 字节降到 4-bit 的 0.5 字节，权重读取时间近似减半，tokens/s 随之抬升；代价侧，激活量化、scale 随 token 进 dispatch 缓冲、累加前按块反量化，都是与 token 数成正比的固定开销，且引入额外 kernel 与寄存器压力。设单层专家权重字节数为 $W$、有效带宽为 $B$、每 token 的量化/反量化开销为 $c$、批大小为 $n$，则单步时间近似为</p>\n<div class=\"formula\">$$T(n)\\approx \\frac{W_{\\text{FP4}}}{B}+\\frac{c}{n},\\qquad \\text{speedup}_{\\text{FP4/FP8}}\\approx\\frac{W_{\\text{FP8}}/B+c_{\\text{FP8}}/n}{W_{\\text{FP4}}/B+c/n}$$</div>\n<p>当 $n$ 小到 $c/n$ 与 $W_{\\text{FP4}}/B$ 同量级时，减半的权重读取被 scale 开销吃掉，吞吐收益被抵消——这正是小 batch decode 的失效区。反过来，长 prefill、超大 batch 的请求形态也不适配：prefill 阶段是计算受限而非带宽受限，FP4 MMA 虽在 tcgen05 上吞吐可达 FP8 的 2 倍，但激活 outlier 在长序列上更易触发 per-token scale 的精度问题，收益不如 decode 明确。长度分布上，短 prompt + 长输出（对话、agent 循环）最契合；超长上下文请求的主要成本落在 KV cache 读取（仍为 FP8/BF16），NVFP4 对这部分没有贡献，投入产出比下降。</p>\n<p>负载不对时的失效是分层的，需按症状定位：</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>主要症状</th><th>根因</th></tr></thead><tbody><tr><td>批大小过小</td><td>吞吐不升反降</td><td>scale 反量化 kernel 与寄存器压力占比高</td></tr><tr><td>激活 outlier 密集</td><td>路由打分漂移、专家选择错误</td><td>per-token/per-block scale 校准不当</td></tr><tr><td>离线校准分布偏移</td><td>combine 后误差逐层放大</td><td>权重 scale 与运行时激活分布不一致</td></tr><tr><td>长上下文为主</td><td>端到端收益被稀释</td><td>成本主体在 KV cache，非专家权重</td></tr></tbody></table>\n<p>工程判断上，把 NVFP4 的启用条件写成可观测的准入规则，而不是全局默认：以 decode 阶段的实测 tokens/s 与尾时延为判据，在小 batch 区间保留 FP8 路径作为回退；对路由打分做在线监控，一旦专家选择分布相对 FP8 基线出现系统性偏移即触发重校准或局部回退 BF16。规模上限受 outlier 敏感性与 scale 开销共同约束，材料未给出具体专家数上限，因此容量规划应按“每 token 激活专家数 × 每专家权重字节数”估算带宽需求，并把 scale 开销作为独立项计入 SLO 预算，而不是假设减半必然线性兑现。</p>\n<h3 id=\"alg-nvfp4-moe-quant-sec-25\">二十五 · 硬件档位与并行拓扑的绑定关系</h3>\n<p>NVFP4 部署的第一个硬约束是 tcgen05 FP4 MMA 的可用性：SM100/SM103 上 FP4 MMA 是原生指令，SM90 及更早的 Hopper 架构没有这条路径，把 NVFP4 权重搬到 H100 上只能走“反量化回 BF16 再算”的退化路线，带宽收益被反量化 kernel 吃掉，得不偿失。因此硬件档位的选择不是“越新越好”的泛泛判断，而是“FP4 MMA 是否在关键路径上”的二值判断：B200/B300 单卡与 GB200/GB300 NVL72 机架都满足，区别只在并行拓扑的展开方式。</p>\n<p>并行拓扑要围绕一个事实设计：decode 阶段每 token 需读取全部激活专家的权重，专家权重占显存主体，所以瓶颈是显存带宽而不是算力。拓扑的第一优先级是让专家权重尽量留在本地 HBM、减少跨卡搬运；第二优先级才是把 FP4 MMA 的吞吐用满。工程上常见的做法是专家并行（EP）把专家切到不同 rank，配合张量并行（TP）切单个专家的中间维度，形成 EP×TP 的二维网格。EP 维度决定 All-to-All 的规模，TP 维度决定单卡上 FP4 MMA 的 tile 形状是否对齐 tcgen05 的 MMA 指令粒度。这里不展开 All-to-All 调度本身（见同模块“专家并行 All-to-All 调度”），只强调一个判断：EP 越大，All-to-All 传输的激活体积越小但跳数越多；NVFP4 把激活压到 4-bit 后，单次传输体积相比 FP8 减半，这直接改变了 EP 的盈亏平衡点——原本因为带宽不够而不敢放大的 EP 度，在 NVFP4 下可以往上推一档。</p>\n<p>具体例子：一个 8 卡 B200 节点，专家总数按层切分后每卡承载若干专家，TP=2 切专家内维度、EP=4 切专家分组。若沿用 FP8 激活，All-to-All 每 token 的 dispatch 缓冲是 1 字节/元素；切到 NVFP4 后是 0.5 字节/元素外加每 16 元素一个 FP8 scale（即 0.5 字节/元素 + 0.0625 字节/元素 ≈ 0.5625 字节/元素），净带宽约为 FP8 的 56%。这个比例决定了 EP 度可以放大而不撑爆 NVLink 5 的链路预算。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-26\">二十六 · 量化方案的组合选择：权重离线、激活在线</h3>\n<p>部署配方里量化方案不是单一开关，而是“权重离线校准 + 激活运行时量化”的两段式。权重侧在离线阶段对每个专家按 16 元素块计算 FP8 scale，权重舍入到 E2M1，scale 与权重一起常驻显存；激活侧在运行时按 token 分组量化到 NVFP4，scale 随 token 一起进入 dispatch 缓冲。两段式的关键不对称在于：权重分布稳定、可以反复校准；激活分布随输入漂移、只能在线估计。这个不对称直接决定了失败模式的位置——权重离线校准与运行时激活分布不一致时，NVFP4 量化误差会累积到 combine 后激活，逐层放大影响输出质量。</p>\n<p>量化粒度的选择要写成可执行的判据。per-tensor scale 实现最简单、寄存器压力最小，但对 outlier 最敏感；per-block（16 元素）scale 是 NVFP4 的原生粒度，精度与开销平衡最好；per-token scale 在激活侧能吸收 token 间的动态范围差异，但需要额外的 reduce 与广播。工程判据是：权重侧固定 per-block（16 元素），因为权重离线可校准、块内分布可控；激活侧默认 per-token，当发现路由打分漂移时退到 per-token + per-block 的混合粒度。公式上，块内反量化在累加前执行：</p>\n<div class=\"formula\">$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$</div>\n<p>其中 x 为 16 元素块内原始值，s 为该块共享的 FP8 scale，x_q 为 E2M1 量化值。累加器保持 FP32，块内按 s_b^w·s_b^x 反量化后累加，combine 后激活反量化回 BF16 进入下一层。KV cache 不参与这条链路，仍保持 FP8/BF16——这一点常被误配，把 KV 也压到 4-bit 会引入与权重激活无关的精度损失，且 KV 的读写模式与分组 GEMM 不同，收益不成比例。</p>\n<p>代价侧要算清楚：反量化 scale 引入额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略，吞吐收益被抵消。具体例子：batch=1 的 decode 步，每层专家 GEMM 的计算量极小，反量化 kernel 的启动与寄存器占用成为主导项，此时 NVFP4 相对 FP8 的净收益可能被压到接近零；batch 增大后 GEMM 主导，收益才显现。因此量化方案的部署配方必须与批调度参数联动，而不是孤立选择。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-27\">二十七 · KV 策略与显存预算的分配</h3>\n<p>NVFP4 把权重与激活压到 4-bit 后，显存预算的分配格局发生变化：专家权重占用下降，KV cache 的相对占比上升。部署配方要重新做一次显存预算的重新平衡，而不是沿用 FP8 时代的分配比例。KV 策略在这里的角色是“不动的锚”——KV cache 保持 FP8/BF16，意味着它的每 token 显存占用不随 NVFP4 改变，于是权重压缩释放出来的显存可以直接转化为更大的 KV 池或更大的并发批。</p>\n<p>具体机制上，分页 KV 与专家权重共存显存的管理（见同模块“分页 KV 与专家权重共存显存”）提供的是分配器层面的能力，本部分只给预算判据：设单卡 HBM 容量为 C，专家权重占用 W_q（NVFP4 后约为 FP8 的一半），KV 每 token 占用 k，则最大并发 token 数约为 (C − W_q − 运行时缓冲)/k。NVFP4 把 W_q 减半，等号右边的分子变大，直接抬升可承载的并发 token 数。这个判据的工程含义是：在 SLO 关注尾时延的场景下，权重压缩换来的显存应优先给 KV 池，而不是给更大的 batch——因为尾时延由最长序列的 KV 驻留决定。</p>\n<p>代价侧：KV 保持 FP8/BF16 意味着 decode 阶段每步仍要读取 KV，KV 带宽不随 NVFP4 下降，于是当 batch 很大、KV 读取成为主导时，NVFP4 的权重带宽收益被稀释。具体例子：长上下文、大 batch 的 decode，每 token 的 KV 读取量远超单次专家权重读取量，此时 tokens/s 的提升幅度明显小于短上下文场景。部署配方因此要按上下文长度分档：短上下文档把显存收益给并发，长上下文档把收益给 KV 池容量并接受较小的 batch。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-28\">二十八 · 调度参数：批大小、分块与 piggyback</h3>\n<p>调度参数是 NVFP4 部署配方里最容易被忽略的一环，因为量化收益的兑现依赖 batch 落在“GEMM 主导”区间。批大小受显存带宽约束，材料未给出具体批大小与 SLO 数值，所以配方要写成参数化的判据而非固定值：以“反量化 scale 开销 / GEMM 主体耗时”作为批大小的选择指标，当该比值高于阈值时增大 batch，直到比值降到可接受区间或显存触顶。</p>\n<p>连续批处理与分块预填的配合要点：预填阶段是 compute-bound，FP4 MMA 的 2 倍吞吐在这里最能兑现；decode 阶段是 bandwidth-bound，收益来自权重读取减半。分块预填与解码 piggyback（见同模块“分块预填与解码 piggyback”）把两类负载混跑，NVFP4 下要重新校准 chunk 大小——预填 chunk 太大时 decode 步被推迟，尾时延变差；chunk 太小时预填的 FP4 MMA 利用率不足。伪代码思路：</p>\n<ul>\n<li>每步先按 decode 队列的 token 数估算权重读取带宽需求；</li>\n<li>若剩余带宽预算足够，插入一个预填 chunk，chunk 大小按 FP4 MMA tile 对齐；</li>\n<li>预填 chunk 与 decode 步共享同一批专家权重读取，piggyback 摊薄带宽；</li>\n<li>若反量化 scale 开销占比超过阈值，则本步不插预填，避免寄存器压力叠加。</li>\n</ul>\n<p>代价侧：调度参数与量化方案是耦合的，per-token 激活 scale 需要额外的 reduce 与广播，在小 batch 下这笔开销的相对占比更高；把 batch 拉大能摊薄它，但 batch 拉大又受 KV 显存约束。具体例子：一个短上下文、高并发的在线服务，batch 可以拉到较大，NVFP4 的权重带宽收益充分兑现，tokens/s 提升明显；同一套配置搬到长上下文场景，KV 显存先触顶，batch 被迫缩小，scale 开销占比回升，收益收窄。配方因此要按场景给出两套调度参数，而不是一套打天下。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-29\">二十九 · 可复现的配置思路：从判据到参数</h3>\n<p>把上述四节收敛成一条可复现的配置路径，顺序是：先定硬件档位（tcgen05 FP4 MMA 是否可用），再定量化方案（权重 per-block 离线、激活 per-token 在线、KV 保持 FP8/BF16），再定并行拓扑（EP×TP 网格，EP 度按 NVFP4 后的 All-to-All 体积重新放大），最后定调度参数（批大小按 scale 开销比值选，预填 chunk 按 FP4 MMA tile 对齐并与 decode piggyback）。每一步都有明确的判据，而不是靠调参试错。</p>\n<p>配置思路里要写清楚验收指标：tokens/s、尾时延、路由打分漂移量、困惑度损失。材料给出的锚点是分组 GEMM 吞吐可达 FP8 的 2 倍、微缩放精度损失在 MoE 上通常 &lt;1% 困惑度、权重与激活带宽相比 FP8 减半。验收时若发现困惑度损失超出预期，第一排查点是激活量化的 outlier 处理（per-token 还是 per-block），第二排查点是权重离线校准与运行时激活分布的一致性；若发现 tokens/s 收益不及预期，第一排查点是 batch 是否落在 GEMM 主导区间，第二排查点是反量化 scale kernel 的寄存器压力。</p>\n<p>失败模式的工程处置要写进配方：4-bit 激活量化对 outlier 敏感，校准不当会导致路由打分漂移、专家选择错误——处置方式是保留一份 BF16 或 FP8 的路由打分旁路，仅对打分用高精度、对 GEMM 用 NVFP4，把量化误差挡在路由之外；权重离线校准与运行时激活分布不一致时误差逐层放大——处置方式是定期用线上流量重校准权重 scale，或在层间插入轻量的激活范围监控。这两条处置都不改变 NVFP4 的主链路，只在其边界上加护栏。</p>\n<p>最后一个工程判断落在并行拓扑与量化方案的耦合上：EP 度放大后，All-to-All 传输的激活是 4-bit 加 scale，接收端要先反量化再进 FP4 MMA，这条链路上的 kernel 融合程度决定了 EP 放大的净收益。若 dispatch 缓冲的反量化与 GEMM 的 scale 反量化能融进同一个 kernel，EP 放大的收益接近线性；若分成两个 kernel，中间结果的写回会吃掉一半带宽收益。配方里应把“dispatch 反量化是否与 GEMM 融合”作为 EP 度能否放大的前置条件，而不是事后优化项。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-30\">三十 · 部署配方的边界：什么条件下 NVFP4 才真正兑现带宽收益</h3>\n<p>这套配方的硬性门槛是硬件档位必须原生支持 tcgen05 FP4 MMA——不是所有 Blackwell 档位都值得上 NVFP4。若某档位 FP4 MMA 吞吐与 FP8 拉不开差距，权重与激活各压到 4-bit 只带来带宽减半，却要付出反量化 scale 的额外 kernel 与寄存器压力，净收益可能为负。并行拓扑上，专家并行的 All-to-All 传输的是 4-bit 权重索引与激活，带宽相比 FP8 减半，因此 EP 组内通信不再是瓶颈，反而 TP 组内的激活同步与 combine 后的 BF16 反量化成为新的时延来源；拓扑设计应把 EP 度调大、TP 度收紧。KV cache 保持 FP8/BF16 不动，意味着 KV 显存占用不随 NVFP4 下降，长上下文场景下 KV 会成为新的容量约束。</p>\n<p>失效条件集中在三处。其一，4-bit 激活量化对 outlier 敏感，per-token 或 per-block scale 校准不当会让路由打分漂移、专家选择错误——MoE 的路由是离散决策，打分误差被放大成整条专家路径的错配，困惑度损失远不止权重侧的 &lt;1%。其二，离线校准的专家权重分布与运行时激活分布不一致时，NVFP4 量化误差经分组 GEMM 累积到 combine 后激活，逐层放大。其三，小 batch decode 时 scale 反解开销占比不可忽略，吞吐收益被抵消。用公式刻画单 token 专家权重读取时间：</p>\n<div class=\"formula\">$$T_{\\text{read}}=\\frac{N_{\\text{act}}\\cdot P_{\\text{exp}}\\cdot b_w}{B_{\\text{HBM}}},\\quad b_w\\in\\{1\\text{B (FP8)},\\,0.5\\text{B (NVFP4)}\\}$$</div>\n<p>其中 $$N_{\\text{act}}$$ 为激活专家数、$$P_{\\text{exp}}$$ 为单专家参数量、$$b_w$$ 为每权重字节数。NVFP4 把 $$b_w$$ 减半即近似把 $$T_{\\text{read}}$$ 减半，但只有当 batch 足够大、scale 反解开销被摊薄时，这部分节省才转化为 tokens/s。可复现的配置思路是：先按“FP4 MMA 是否原生、EP 带宽是否减半后仍富余、KV 是否另有压缩”三问定档位；再以离线校准的每 16 元素 FP8 scale 为基线，运行时激活强制 per-token scale 并监控路由打分漂移；最后用尾时延而非均值 tokens/s 作为 SLO 判据，因为小 batch 尾部的 scale 开销正是收益反转点。</p>\n<table class=\"mini\"><thead><tr><th>配置维度</th><th>取值</th><th>失效信号</th></tr></thead><tbody><tr><td>硬件档位</td><td>原生 tcgen05 FP4 MMA</td><td>FP4 与 FP8 吞吐无差</td></tr><tr><td>并行拓扑</td><td>EP 大、TP 小</td><td>combine 反量化成瓶颈</td></tr><tr><td>量化方案</td><td>权重 16 元素块 FP8 scale，激活 per-token</td><td>路由打分漂移</td></tr><tr><td>KV 策略</td><td>FP8/BF16 不变</td><td>长上下文 KV 容量吃紧</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-moe-quant-sec-31\">三十一 · 显存与带宽账：收益先落在权重读取上</h3>\n<p>NVFP4 的系统收益必须按“每 token 要搬多少字节”来算，而不是按权重文件大小算。MoE decode 阶段每个 token 都要经过路由选中的专家，激活专家权重是显存读取的主体；FP8 下每个权重元素占 1 字节，NVFP4 下占 0.5 字节，外加每 16 元素一个 FP8 scale（0.5 字节/元素），合计仍是 0.5 字节/元素量级，相对 FP8 的权重读取字节数近似减半。设单 token 激活专家权重元素数为 $N_e$，则单 token 权重读取字节为</p>\n<div class=\"formula\">$$B_{\\text{token}} \\approx N_e \\cdot \\left(0.5 + \\frac{0.5}{16}\\right) \\ \\text{bytes}$$</div>\n<p>这一项直接决定 decode 的 tokens/s 上限：在带宽受限区间，$ \\text{tokens/s} \\lesssim \\text{HBM 带宽} / B_{\\text{token}}$。因此 NVFP4 的第一笔系统代价收益是“专家权重读取时间近似减半”，而不是算力翻倍；算力侧的 2 倍 FP4 MMA 吞吐只有在分组 GEMM 已经吃满 tensor core 时才兑现。工程上要区分两种 regime：小 batch decode 是纯带宽受限，权重读取减半几乎线性抬 tokens/s；大 batch 或长预填时算力占比上升，FP4 MMA 的 2 倍吞吐才开始成为主项。显存容量侧，权重压到 4-bit 后单卡可容纳的专家数上升，但 KV cache 仍保持 FP8/BF16，不随权重一起缩小，所以容量规划不能按“权重减半则显存减半”估算。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-32\">三十二 · 反量化 scale 的固定开销：小 batch 时先崩的地方</h3>\n<p>NVFP4 的块内反量化不是免费的。每个 16 元素块共享一个 FP8 scale，分组 GEMM 在累加前要按块取 scale 做乘法，累加器为 FP32；这引入额外的 scale 加载、寄存器占用与指令发射。设单 token 激活专家权重元素数为 $N_e$，块数 $N_e/16$，每块反量化至少一次 scale 乘法，则反量化指令数随 $N_e/16$ 线性增长，与 MMA 主循环争用发射槽与寄存器。小 batch decode 时 MMA 本身占用不高，这部分固定开销占比不可忽略，吞吐收益被抵消——这是规模上去后第一个崩点：不是带宽不够，而是 scale 开销把省下来的带宽时间又吃回去。判断方法是看 kernel 的 issue slot 利用率与寄存器压力：若反量化 kernel 的寄存器溢出到 local memory，实际带宽会高于理论值，tokens/s 不升反降。缓解手段是把 scale 折叠进 MMA 的输入布局、让 scale 随 dispatch 缓冲一起预取，避免在热循环里做额外的全局加载。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-33\">三十三 · All-to-All 通信：4-bit 激活让传输量减半，但尾延迟不按比例缩</h3>\n<p>专家并行下，dispatch 阶段要把激活按 token 送到目标专家所在 rank。NVFP4 把激活压到 4-bit，scale 随 token 一起进入 dispatch 缓冲，All-to-All 传输的激活字节数相比 FP8 减半；权重索引也以 4-bit 形式传输。设单 token 激活向量维度 $d$、目标专家数 $k$、每 rank 传输的 token 数为 $T_r$，则单轮 dispatch 的激活传输量近似为</p>\n<div class=\"formula\">$$V_{\\text{dispatch}} \\approx T_r \\cdot k \\cdot d \\cdot \\left(0.5 + \\frac{0.5}{16}\\right) \\ \\text{bytes}$$</div>\n<p>传输量减半直接降低 All-to-All 的带宽占用，在 NVLink 5 域内意味着同样的链路预算可以承载更多并发 token，或把同样 token 数的通信时间压到接近一半。但尾延迟不按字节比例缩：All-to-All 的完成时间由最慢的那条链路决定，而 scale 与 4-bit 激活需要打包、对齐、在接收端重新组装成块结构，这些打包/解包步骤是固定开销，在消息很小时占比更高。规模上去后第二个崩点是通信的尾延迟：当专家并行度提高、每 rank 分到的 token 变少，单条消息变小，打包开销与同步开销压过带宽收益，P99 时延不再随 4-bit 下降。工程判断是看消息大小分布：若大量消息落在“打包开销主导”的小消息区间，应合并 dispatch 缓冲、按块对齐打包，而不是继续加并行度。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-34\">三十四 · 功耗与吞吐的耦合：FP4 MMA 的能效不是线性的</h3>\n<p>tcgen05 原生支持 FP4 MMA，分组 GEMM 吞吐可达 FP8 的 2 倍，但能效并不按吞吐线性缩放。FP4 MMA 在同样 MMA 周期内搬运的权重字节减半，HBM 读取功耗随之下降；然而反量化 scale 的额外 kernel、寄存器压力与指令发射会增加 SM 的动态功耗，且小 batch 时这部分固定功耗摊到很少的 token 上，每 token 能耗反而变差。设单 token 能耗为 $E_{\\text{token}} = P_{\\text{total}} \\cdot t_{\\text{token}}$，其中 $t_{\\text{token}}$ 由带宽与 scale 开销共同决定；NVFP4 把 $t_{\\text{token}}$ 的带宽项减半，但 $P_{\\text{total}}$ 中的反量化项上升，净效应取决于 batch 大小。规模上去后第三个崩点是功耗墙：当并发 token 数上升、SM 长期处于 FP4 MMA 高占用，反量化与 MMA 同时争用发射与寄存器，功耗接近封装上限，频率回落，tokens/s 的线性增长被打破。容量规划应把“每 token 焦耳”作为与 tokens/s 并列的指标，而不是只看峰值吞吐。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-35\">三十五 · 精度漂移的尾延迟放大：路由打分与逐层累积</h3>\n<p>4-bit 激活量化对 outlier 敏感，需 per-token 或 per-block scale；校准不当会导致路由打分漂移、专家选择错误。路由错误在系统层面的表现不是平均质量下降，而是尾延迟：被错误路由的 token 进入负载更重的专家，该专家的队列变长，P99 时延抬升；同时错误专家的权重读取模式更分散，带宽利用率下降。更隐蔽的是权重离线校准与运行时激活分布不一致时，NVFP4 量化误差累积到 combine 后激活，逐层放大影响输出质量——这类误差不体现在单层 kernel 时间上，而体现在“同样 SLO 下需要更多重试或更长生成长度”，从而间接抬高尾延迟。规模上去后第四个崩点是精度漂移与尾延迟的耦合：专家数越多、路由越稀疏，单个 token 的量化误差被放大到路由决策的概率越高。工程上应把路由打分的量化误差纳入监控，按 per-token scale 的分布做漂移告警，而不是只在离线校准阶段验证困惑度损失 <1%。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-36\">三十六 · 规模上去后哪里先崩：按 regime 排序</h3>\n<p>把上述代价按 regime 排序，可以得到一张工程判断表。小 batch decode（带宽受限、MMA 占用低）先崩在反量化 scale 的固定开销：带宽省下来的时间被 scale 加载与寄存器压力吃掉，tokens/s 不升。中等并发、专家并行度高时先崩在 All-to-All 尾延迟：消息变小后打包与同步开销主导，P99 不随 4-bit 下降。大并发、SM 高占用时先崩在功耗墙：反量化与 FP4 MMA 争用发射槽，频率回落，吞吐线性被打破。专家数继续上升、路由更稀疏时先崩在精度漂移：路由打分误差放大，错误专家的队列与分散读取抬高尾延迟。这张表的用法是：先测当前 regime 的瓶颈项，再决定是否值得把权重与激活都压到 NVFP4；若瓶颈在 scale 开销或通信尾延迟，单纯换 4-bit 不会兑现“读取时间近似减半”的收益。</p>\n<table class=\"mini\"><thead><tr><th>Regime</th><th>先崩的项</th><th>可观测信号</th><th>工程动作</th></tr></thead><tbody><tr><td>小 batch decode</td><td>反量化 scale 固定开销</td><td>寄存器溢出、issue slot 饱和、tokens/s 不升</td><td>scale 预取与布局折叠，避免热循环全局加载</td></tr><tr><td>高专家并行</td><td>All-to-All 尾延迟</td><td>小消息占比高、P99 不随 4-bit 下降</td><td>合并 dispatch 缓冲、按块对齐打包</td></tr><tr><td>大并发高占用</td><td>功耗墙</td><td>频率回落、每 token 焦耳变差</td><td>把每 token 焦耳纳入容量规划</td></tr><tr><td>稀疏路由大规模</td><td>精度漂移放大尾延迟</td><td>路由打分误差分布漂移、错误专家队列变长</td><td>per-token scale 漂移告警，纳入 SLO 监控</td></tr></tbody></table>\n<p>落到具体机制上：NVFP4 的收益边界由“权重读取字节减半”与“scale 开销、通信打包、功耗、精度漂移”四项代价共同划定。规模上去后最先崩的通常不是带宽，而是小 batch 下的 scale 固定开销与高并行下的 All-to-All 尾延迟；这两项都要求把 scale 与 4-bit 激活的打包路径做成可预取、可合并的形态，否则 FP4 MMA 的 2 倍吞吐只停留在纸面。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-37\">三十七 · 带宽账本的另一面：NVFP4 在什么规模上先撞墙</h3>\n<p>把 NVFP4 的收益写成一行账很容易：专家权重从 1 字节降到 0.5 字节，decode 每 token 的权重读取时间近似减半，tokens/s 随之抬升；tcgen05 的 FP4 MMA 又让分组 GEMM 吞吐达到 FP8 的 2 倍。但这条账只在“权重带宽是唯一瓶颈”的假设下成立。真实系统的每 token 代价可以写成 <span class=\"formula\">$$T_{\\text{token}}\\approx \\underbrace{\\frac{0.5\\,W_{\\text{exp}}}{B_{\\text{HBM}}}}_{\\text{权重读取}}+\\underbrace{\\frac{A_{\\text{act}}}{B_{\\text{HBM}}}}_{\\text{激活读写}}+\\underbrace{t_{\\text{scale}}(N_{\\text{blk}})}_{\\text{反量化}}+\\underbrace{\\frac{V_{\\text{kv}}}{B_{\\text{HBM}}}}_{\\text{KV 读取}}$$</span> 其中 $W_{\\text{exp}}$ 是每 token 激活专家的权重字节数，$N_{\\text{blk}}$ 是块数（每 16 元素一块）。NVFP4 只压缩了第一项，第二项随激活量化同比缩小，第三项却随块数线性增长，第四项完全不动——KV cache 仍保持 FP8/BF16。这意味着当专家权重被压到足够小、KV 读取与 scale 开销开始占据主导时，继续压权重的边际收益迅速衰减，系统进入“量化已到位、瓶颈已转移”的区间。</p>\n<p>第一个先崩的地方是小 batch decode 的 scale 开销。每 16 元素共享一个 FP8 scale，块数等于元素数除以 16，反量化要在累加前逐块执行，这引入额外 kernel 启动与寄存器压力。批大小越小，单次 GEMM 的有效计算量越小，scale 处理占用的时间比例越高；材料明确指出小 batch decode 时 scale 开销占比不可忽略，吞吐收益会被抵消。工程判断是：NVFP4 的吞吐红利在中等以上 batch、权重读取主导的区间最明显；当 batch 被压到很小以保尾延迟时，必须把反量化融合进 MMA 的累加路径（累加器保持 FP32、块内按 scale 反量化），否则多出来的 kernel 会把省下的带宽重新吃掉。这里没有免费的午餐，只有把 scale 开销藏进流水线。</p>\n<p>第二个失效条件是 outlier 与校准漂移。4-bit 激活量化对 outlier 敏感，需要 per-token 或 per-block scale；校准不当会让路由打分漂移，专家选择错误。这条失败路径的系统代价不是精度数字，而是负载形态的畸变：被错误选中的专家在 All-to-All 上产生额外的 4-bit 权重索引与激活传输，某些 rank 的 dispatch 缓冲被撑大，尾延迟抬升。更隐蔽的是离线权重校准与运行时激活分布不一致——权重按 16 元素块算出的 FP8 scale 是离线固定的，而运行时激活分布随输入漂移，量化误差在 combine 后激活上累积，逐层放大。规模上去以后，专家数增多、每 token 路由更稀疏，单个专家的校准样本变少，这种不一致更容易出现，于是“精度损失 <1% 困惑度”的经验在长尾输入上不再成立。</p>\n<p>第三个边界是通信与功耗的耦合。All-to-All 传输 4-bit 权重索引与激活，带宽相比 FP8 减半，这缓解了 NVL72 域内 dispatch 的压力；但通信量减半不等于通信时间减半——消息变小后，固定开销（同步、缓冲管理、NIXL 传输建立）占比上升，尾延迟由最慢的那条链路决定。功耗侧，FP4 MMA 的能效优于 FP8，但反量化 kernel 与寄存器压力带来的额外活动会部分抵消；在功耗封顶的机柜里，真正的约束往往不是峰值算力而是持续吞吐下的热预算。规模上限因此受三重约束：outlier 敏感性与 scale 开销限制 batch 下限，校准漂移限制专家数与稀疏度上限，通信固定开销限制并行拓扑的扩展半径。材料未给出具体专家数上限与 SLO 数值，工程上应以“权重读取是否仍占每 token 时间的主导份额”作为是否继续扩大的判据，而不是以困惑度损失单一指标放行。</p>\n<h3 id=\"alg-nvfp4-moe-quant-sec-38\">三十八 · 精度失败的三种形态：outlier、路由漂移、误差累积</h3>\n<p>NVFP4 的精度失败不是单一现象，而是沿三条不同路径发生，诊断时必须先分清是哪一条，否则回滚手段会打偏。第一条是 <strong>outlier 击穿块内动态范围</strong>：每 16 元素共享一个 FP8 scale，块内只要出现一个幅值远超同伴的激活，scale 就被这一个值拉高，其余 15 个元素被压到 E2M1 的低位甚至归零。E2M1 只有 1 位符号、2 位指数、1 位尾数，可表示值稀疏，块内动态范围一旦被 outlier 独占，有效精度骤降。第二条是 <strong>路由打分漂移</strong>：MoE 的 gate 打分通常在前一层激活上计算，若该激活经过 NVFP4 量化后反量化回 BF16，数值上的微小偏移足以改变 top-k 专家排序，尤其在两个专家得分接近时。第三条是 <strong>combine 后误差累积</strong>：专家输出按 gate 权重加权求和，量化误差随层数叠加，单层看不出来，深层才暴露。</p>\n<p>把三条路径写成可观测的量。块内 outlier 程度可用动态范围比刻画：</p>\n<div class=\"formula\">$$r_b=\\frac{\\max_{i\\in b}|x_i|}{\\text{median}_{i\\in b}|x_i|}$$</div>\n<p>r_b 越大，块内被 outlier 主导越严重，E2M1 对多数元素的表示越粗。工程上不需要对每个块做统计，只需在若干代表性层上采样，观察 r_b 的分布尾部；尾部一旦拉长，说明 per-block scale 不够，应切换到 per-token scale 或缩小区块。路由漂移则用 top-k 集合的 Jaccard 重叠率监控：同一 token 在 BF16 路径与 NVFP4 路径下的专家集合交集除以并集，重叠率下降即漂移发生。误差累积用逐层输出与 BF16 参考的余弦相似度追踪，重点看 combine 之后而非专家内部。</p>\n<p>代价上要认清：精度问题不会表现为报错，而是表现为质量指标缓慢劣化与路由分布偏移，排查成本高。一个具体例子：某层 gate 打分在 0.51 与 0.49 两个专家间切换，NVFP4 量化把前者压到 0.49 以下，top-1 专家换人，该 token 走了一条完全不同的专家路径，输出偏差远超量化本身的数值误差。这类失败无法靠调 scale 上限修复，只能靠 gate 路径保持高精度或对 gate 输入单独走 BF16。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-39\">三十九 · OOM 与显存账本：量化省下的不是全部</h3>\n<p>NVFP4 把权重与激活压到 4-bit，直觉上显存应大幅下降，但 OOM 仍会发生，原因是显存账本里量化只覆盖了一部分。权重按 16 元素块存 E2M1 加一个 FP8 scale，实际每元素占用是 4 bit 加 8/16 bit 的 scale 开销，即 4.5 bit 量级而非纯 4 bit；激活的 scale 随 token 进入 dispatch 缓冲，All-to-All 传输的缓冲按 4-bit 载荷加 scale 计算；KV cache 明确保持 FP8/BF16，不参与量化；反量化 kernel 需要 FP32 累加器与中间缓冲，tcgen05 FP4 MMA 的累加器为 FP32，这部分工作集在小 batch 时占比反而上升。</p>\n<p>把峰值显存拆成可核算的项：</p>\n<div class=\"formula\">$$M_{\\text{peak}}=M_{w}+M_{a}+M_{\\text{kv}}+M_{\\text{disp}}+M_{\\text{acc}}+M_{\\text{frag}}$$</div>\n<p>其中 M_w 为本地专家权重（4-bit 加 scale），M_a 为激活与 scale，M_kv 为 KV cache，M_disp 为 dispatch/combine 缓冲，M_acc 为 FP32 累加器与反量化临时区，M_frag 为显存碎片。诊断 OOM 的第一步不是降 batch，而是确认哪一项在涨：若 M_disp 随并发线性涨，说明 All-to-All 缓冲未复用；若 M_frag 显著，说明专家权重分页与 KV 分页交错分配造成碎片，这与分页 KV 与专家权重共存的布局直接相关。</p>\n<p>系统代价上，量化带来的显存节省会被反量化工作集部分吃掉，尤其在 decode 小 batch 时，FP32 累加器与 scale 反量化 kernel 的寄存器压力使 occupancy 下降，吞吐收益被抵消。具体例子：批大小很小时，每 token 仍需读取全部激活专家权重，权重读取时间近似减半的收益被 scale 反量化 kernel 的启动与寄存器开销摊薄，端到端 tokens/s 提升远小于带宽减半的理论值。此时正确判断是 scale 开销占比过高，而非显存不足，回滚方向应是减少反量化 kernel 次数（融合进 MMA 后处理）而不是退回 FP8。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-40\">四十 · 批抖动与路由不均：吞吐曲线的锯齿</h3>\n<p>批抖动指连续批处理下 tokens/s 随并发出现非单调波动，NVFP4 会放大这一现象。根因是量化路径的固定开销与批大小非线性：反量化 scale 的 kernel 启动、dispatch 缓冲的分配与回收、FP4 MMA 的 tile 对齐都有最小粒度，小 batch 时这些固定成本摊到每个 token 上很重，batch 增大后摊薄，但一旦超过某个点，专家权重读取带宽成为瓶颈，tokens/s 又走平。两条曲线叠加形成锯齿。</p>\n<p>路由不均则是另一维度：MoE 的专家负载天然偏斜，NVFP4 不改变路由算法，但会改变专家被选中的概率分布——量化误差使部分专家得分系统性偏低，长期看这些专家被冷落，而热门专家承受全部流量。热点专家所在的 GPU 上，权重读取与 FP4 MMA 排队，尾延迟抬升；冷门专家所在 GPU 空闲。诊断要看两个量：每专家的 token 计数分布（偏斜度）与每 GPU 的专家命中率。前者用基尼系数或 top-1 专家占比衡量，后者看单卡实际执行的专家 GEMM 次数是否与其权重占比匹配。</p>\n<p>代价上，路由不均直接转化为尾延迟尖刺与 GPU 利用率下降，且与容量因子路由正交——容量因子能截断溢出，但不能修正量化引起的得分偏移。具体例子：某专家因激活 outlier 被量化压低得分，从热门变为冷门，其权重仍占显存但几乎不参与计算，等于显存浪费加算力闲置；与此同时原第二热门专家承接溢出流量，其所在卡成为瓶颈。监控上应把「专家得分分布」与「专家实际执行次数」并列看，两者背离即为量化引起的路由偏移，而非真实负载变化。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-41\">四十一 · 尾延迟尖刺的定位：从 P99 回溯到块</h3>\n<p>尾延迟尖刺在 NVFP4 部署里通常不是平均值问题，而是少数请求撞上了最坏路径。定位方法是把 P99 请求的耗时按阶段拆开：激活量化、dispatch、FP4 MMA、反量化、combine。尖刺若集中在激活量化阶段，说明该请求的激活块出现极端 outlier，scale 计算与舍入路径变长或触发回退；若集中在 MMA 阶段，说明该请求路由到了热点专家，排队；若集中在反量化，说明 scale kernel 与主 kernel 的同步点被放大。</p>\n<p>可用的诊断伪代码思路：对每个请求记录各阶段时间戳与路由到的专家集合，按 P99 分位筛选后聚类，看尖刺请求是否共享同一专家或同一层。若共享，则是路由不均；若不共享但都含大动态范围块，则是 outlier。监控指标应包含每阶段的 P50/P99 比值，比值突增即为该阶段出现长尾。</p>\n<p>系统代价上，尾延迟尖刺的代价是 SLO 违约而非平均吞吐下降，修复它往往要牺牲一点吞吐（例如对尖刺请求走 BF16 回退路径）。具体例子：一个含极端激活值的请求在 NVFP4 路径上量化误差大，输出质量不达标触发重试，重试请求再次进入同一路径，形成延迟与质量的双重尖刺。正确做法是对这类请求做前置检测——块内动态范围比超阈值即走 BF16 专家路径，用少量吞吐换尾延迟稳定。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-42\">四十二 · 监控面与回滚阶梯</h3>\n<p>监控要覆盖四个面，缺一不可。精度面：逐层余弦相似度、top-k 专家重叠率、块内动态范围比尾部。显存面：M_w/M_a/M_kv/M_disp/M_acc 分项与碎片率。吞吐面：tokens/s 随 batch 的曲线、每阶段 P50/P99。路由面：专家得分分布与执行次数分布。四个面共用同一批采样点，避免各监控系统时间戳错位导致误判。</p>\n<p>回滚不是一刀切退回 FP8，而是分级阶梯，按失败形态选择最小代价的一级：</p>\n<table class=\"mini\"><thead><tr><th>级别</th><th>动作</th><th>适用失败形态</th><th>代价</th></tr></thead><tbody>\n<tr><td>L1</td><td>gate 路径与 combine 后激活保持 BF16，仅专家 GEMM 走 NVFP4</td><td>路由打分漂移</td><td>少量带宽与显存回升</td></tr>\n<tr><td>L2</td><td>激活从 per-block 切到 per-token scale，缩小区块</td><td>outlier 击穿</td><td>scale 开销上升，吞吐略降</td></tr>\n<tr><td>L3</td><td>对高动态范围块走 BF16 回退分支</td><td>尾延迟尖刺与质量尖刺</td><td>分支带来控制流开销</td></tr>\n<tr><td>L4</td><td>单层或单专家组退回 FP8 权重</td><td>误差累积集中在特定层</td><td>显存与带宽回升，需重排布局</td></tr>\n<tr><td>L5</td><td>整体退回 FP8 权重加 FP8 激活</td><td>多形态并发且无法定位</td><td>带宽收益全部放弃</td></tr>\n</tbody></table>\n<p>回滚的工程判断依据是「收益是否还在」：NVFP4 的核心收益是专家权重读取时间近似减半与 FP4 MMA 吞吐可达 FP8 的 2 倍。若回滚到 L1 或 L2 后 tokens/s 仍显著高于 FP8 基线，说明收益主要来自权重 4-bit 而非激活 4-bit，应停在低级别；若回滚到 L3 后尾延迟仍不稳，说明问题在路由而非量化，应转去查路由算法而非继续降精度。每次回滚都要记录触发指标与回滚后指标，形成可复用的判定表，避免下次同类失败重新摸索。</p>\n<p>最后落在具体机制上：把「块内动态范围比超阈值即走 BF16 分支」做成编译期可配的守卫，与 FP4 MMA 的 tile 调度绑定，使回退分支不打断主 kernel 的流水；同时把 top-k 专家重叠率作为发布门禁指标，低于阈值即阻止上线。这两条守卫把精度失败从「上线后缓慢劣化」变成「上线前可拦截、上线后可定点回滚」，是 NVFP4 部署里比调 scale 更值得投入的工程动作。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-43\">四十三 · 量化误差如何沿路由链放大：诊断与回滚的工程抓手</h3>\n<p>NVFP4 的失效很少表现为单点数值溢出，而是沿“量化→路由打分→专家选择→combine”链条放大。权重侧离线校准的块内 scale 固定为 <span class=\"formula\">$$s_b=\\frac{\\max_{j\\in b}|w_j|}{\\text{FP8}_{\\max}}$$</span>，一旦线上激活分布漂移（长上下文、领域切换、温度变化），权重校准时的极值与运行时激活极值不再匹配，E2M1 的 4-bit 尾数在块内相对误差被 combine 的加权和逐层累积。诊断抓手是逐层记录路由 logits 的 top-k 边界间隔：若某层 top-1 与 top-2 的 logit 差落入量化噪声量级，该 token 的专家选择即不可信。工程上把这一间隔作为监控指标而非困惑度，因为困惑度是滞后指标，间隔是前置指标。代价是每层多一次 logits 采样与 host 侧归约，在 decode 小 batch 下这部分开销与 scale 反量化 kernel 同量级，必须采样而非全量。</p>\n<p>第二类失效是显存与批抖动。NVFP4 把权重与激活压到 4-bit，但反量化 scale 需要额外 kernel 与寄存器压力，小 batch decode 时 scale 开销占比不可忽略，吞吐收益被抵消。表现为：批大小从个位数抬升时 tokens/s 不升反降，或尾时延尖刺出现在 batch 边界重排瞬间。诊断方法是把 decode 步拆成 dispatch、FP4 MMA、scale 反量化、combine 四段计时，观察哪一段随 batch 非线性增长；若反量化段斜率陡于 MMA 段，说明 scale kernel 已成瓶颈，此时应回滚到 FP8 权重路径而非继续调批。OOM 则多来自 dispatch 缓冲同时驻留 4-bit 激活与 FP8/BF16 KV cache 的峰值叠加，监控应看缓冲高水位而非平均占用。</p>\n<p>路由不均与尾延迟尖刺常同源：某专家被过度选择时，其 All-to-All 分片成为长尾，4-bit 传输虽把带宽减半，但分片不均衡会让最热专家的链路先饱和。诊断用每专家 token 计数的基尼系数与分片传输时延的 P99 对齐看，两者同步抬升即确认路由不均。回滚策略分三级：先关激活量化、保留 NVFP4 权重（精度损失主要来自激活 outlier）；再整体退回 FP8 权重与激活；最后回退校准版本。每级回滚都需重放同一批 trace 比对路由选择一致性，避免把容量因子调整误判为量化问题。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要诊断量</th><th>回滚动作</th></tr></thead><tbody><tr><td>输出质量漂移</td><td>逐层 top-k logit 间隔</td><td>关激活 NVFP4</td></tr><tr><td>小 batch 吞吐倒挂</td><td>反量化段计时斜率</td><td>退回 FP8 权重</td></tr><tr><td>尾时延尖刺</td><td>专家计数基尼系数</td><td>回退校准版本</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-moe-quant-sec-44\">四十四 · 选型的第一维：把量化维度与路由维度解耦</h3>\n<p>NVFP4 权重激活微缩放量化在算法谱系里的位置，必须先与一批容易混淆的邻居切开。容量因子路由与令牌丢弃、专家选择路由、无丢弃块稀疏分组 GEMM、专家并行 All-to-All 调度，这些条目动的是“哪些 token 去哪些专家、每个专家收多少 token、跨卡怎么搬”这一层；NVFP4 动的是“搬过去的那份权重与激活各占几个比特、MMA 用什么精度算”这一层。两者正交：路由算法决定分组 GEMM 的 M 维形状与负载偏斜，量化算法决定这个 GEMM 的字节数与 MMA 指令吞吐。工程上常见的错误是在路由侧已经严重偏斜的部署里先上 NVFP4，结果小 batch decode 的 scale 反量化开销把带宽收益吃掉，却误判为量化本身不划算。</p>\n<p>因此选型第一问不是“精度够不够”，而是“当前瓶颈是否落在专家权重的字节数上”。判据可以直接写成带宽账：decode 每 token 需读取全部激活专家权重，若权重字节数为 <span class=\"inline-math\">B</span>、激活专家数为 <span class=\"inline-math\">k</span>、单卡 HBM 有效带宽为 <span class=\"inline-math\">BW</span>，则单 token 权重读取下界近似为</p>\n<div class=\"formula\">$$t_{\\text{read}} \\approx \\frac{k \\cdot B}{BW}, \\quad B_{\\text{FP8}} = 1\\ \\text{byte/param},\\ B_{\\text{NVFP4}} = 0.5\\ \\text{byte/param} + \\text{scale 开销}$$</div>\n<p>当 <span class=\"inline-math\">\\(t_{\\text{read}}\\)</span> 主导端到端时延时，NVFP4 把 <span class=\"inline-math\">B</span> 减半就是直接减半该分项；当 batch 已经大到 GEMM 进入计算受限区，收益则转移到 tcgen05 FP4 MMA 的吞吐上——材料给出的锚点是分组 GEMM 吞吐可达 FP8 的 2 倍。反过来，若瓶颈在 All-to-All 或 KV cache 带宽，量化专家权重只解决其中一段，需要与分离式专家并行、分页 KV 那几条条目合并评估。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-45\">四十五 · 决策表：五类相邻算法的适用条件</h3>\n<p>下表把同族算法按“动的维度、解决的瓶颈、与本算法的关系”三列对齐。表中不重复各条目自身的机制细节，只保留选型时需要的那一格。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>相邻算法</th><th>动的维度</th><th>典型适用条件</th><th>与 NVFP4 的关系</th></tr>\n</thead>\n<tbody>\n<tr><td>FP8 权重（1 字节）</td><td>数值精度</td><td>HBM 带宽尚有裕量、outlier 分布不稳定、需要最低校准成本</td><td>NVFP4 的前置档位；FP8 不够时才下探 4-bit</td></tr>\n<tr><td>NVFP4 权重激活微缩放</td><td>数值精度 + 字节数</td><td>decode 显存带宽受限、硬件支持 tcgen05 FP4 MMA、可承担离线校准</td><td>本条目的主体</td></tr>\n<tr><td>容量因子路由与令牌丢弃</td><td>负载形状</td><td>专家负载严重偏斜、尾时延超标</td><td>正交；先修形状再谈量化，否则小 batch 放大 scale 开销</td></tr>\n<tr><td>专家选择路由</td><td>路由决策</td><td>路由打分本身是质量瓶颈</td><td>正交但耦合：4-bit 激活量化误差会经打分漂移传导到选择结果</td></tr>\n<tr><td>无丢弃块稀疏分组 GEMM</td><td>GEMM 形状</td><td>不能丢 token、需要保持语义完整</td><td>正交；其块稀疏结构决定 NVFP4 的 16 元素块能否对齐</td></tr>\n<tr><td>分离式专家并行 / All-to-All 调度</td><td>通信拓扑</td><td>跨节点专家分布、通信成为主瓶颈</td><td>互补；NVFP4 让传输的激活与索引字节减半，直接减轻该层压力</td></tr>\n</tbody>\n</table>\n<p>读表的方式是自上而下排除：先用 FP8 做基线，测出 decode 的 <span class=\"inline-math\">\\(t_{\\text{read}}\\)</span> 占比；若该占比高且硬件档位支持 tcgen05 FP4 MMA，再切 NVFP4。切完之后如果尾时延仍不达标，问题多半已不在量化维度，应回到路由与调度那几条条目。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-46\">四十六 · 与 FP8 的取舍：精度预算怎么花</h3>\n<p>FP8 与 NVFP4 的差别不只是字节数，而是误差结构。FP8 的尾数位更宽，单元素相对误差小；NVFP4 用 E2M1，元素本身只有 4 位，精度靠每 16 元素共享一个 FP8 scale 把动态范围拉回来。块内量化写作</p>\n<div class=\"formula\">$$x_{q}=\\operatorname{round}_{\\text{E2M1}}\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max_{16}|x|}{\\text{FP8\\_max}}$$</div>\n<p>这意味着误差由块内最大值主导：一个 outlier 会把 <span class=\"inline-math\">s</span> 抬高，块内其余 15 个元素的有效分辨率随之下降。FP8 在同样位置只需承受一次舍入，NVFP4 则要承受“scale 被 outlier 绑架 + E2M1 粗粒度”双重效应。材料给出的经验锚点是微缩放精度损失在 MoE 上通常 &lt;1% 困惑度，但这个数字的前提是校准到位；一旦离线校准的权重分布与运行时激活分布不一致，量化误差会累积到 combine 后激活并逐层放大。选型判断因此落在精度预算上：若业务对困惑度极敏感、或激活 outlier 分布随输入漂移剧烈，FP8 是更稳的档位；若困惑度有余量、且 decode 带宽是硬约束，NVFP4 的 2 倍 MMA 吞吐与减半字节数才值得付出校准与 outlier 处理的工程成本。</p>\n<p>代价侧要算清 scale 开销。反量化 scale 引入额外 kernel 与寄存器压力，在小 batch decode 时占比不可忽略。设单 token 有效计算量为 <span class=\"inline-math\">C</span>、scale 反量化开销为 <span class=\"inline-math\">S</span>，则收益条件近似为</p>\n<div class=\"formula\">$$\\frac{t_{\\text{read}}^{\\text{FP8}} - t_{\\text{read}}^{\\text{NVFP4}}}{t_{\\text{read}}^{\\text{FP8}}} &gt; \\frac{S}{C}$$</div>\n<p>batch 越小，<span class=\"inline-math\">C</span> 越小而 <span class=\"inline-math\">S</span> 基本不变，右项变大，收益被侵蚀。这正是“先修负载形状再量化”的量化表达：容量因子与令牌丢弃把 batch 与分组形状拉回健康区间后，NVFP4 的收益条件才容易满足。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-47\">四十七 · 与路由类算法的耦合：打分漂移是隐藏的选型成本</h3>\n<p>NVFP4 与专家选择路由看似正交，实则在数值上串联。激活量化到 4-bit 后，路由打分若在同一份量化激活上计算，outlier 引起的块内分辨率下降会改变打分排序，导致专家选择错误；材料把这条列为明确失败模式。选型的工程含义是：如果部署里路由打分与专家 GEMM 共用同一份 NVFP4 激活，就必须接受“量化误差 → 打分漂移 → 选择错误 → combine 后误差放大”的链路，并为此保留 per-token 或 per-block scale 的额外校准；如果路由打分走独立的 BF16/FP8 通路，则这条耦合被切断，NVFP4 只影响 GEMM 数值，选型风险显著下降。后者多一份激活副本的显存与带宽，前者省一份但把风险压在校准上——这是决策表里没有写、但必须逐部署确认的一格。</p>\n<p>与无丢弃块稀疏分组 GEMM 的耦合则在形状侧：NVFP4 的 scale 粒度是每 16 元素一块，块稀疏 GEMM 的稀疏块边界若与 16 元素边界不对齐，就会出现跨块的 scale 拼接，反量化 kernel 需要处理非对齐尾块，寄存器压力上升。选型时应确认稀疏块尺寸是 16 的整数倍，否则要么改稀疏粒度，要么接受尾块开销。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-48\">四十八 · 适用条件清单与规模上限的定性判断</h3>\n<p>把前述判断收敛成一份可执行的准入清单，逐条打勾再上 NVFP4：</p>\n<ul>\n<li>硬件档位支持 tcgen05 FP4 MMA，累加器为 FP32——否则 4-bit 只有带宽收益、拿不到吞吐收益。</li>\n<li>decode 阶段 <span class=\"inline-math\">\\(t_{\\text{read}}\\)</span> 在端到端时延中占主导，且 batch 未被压到极小。</li>\n<li>离线校准流程可对每个专家按 16 元素块稳定产出 FP8 scale，且校准分布与线上激活分布一致。</li>\n<li>激活 outlier 有 per-token 或 per-block scale 兜底，路由打分通路已确认是否与量化激活共用。</li>\n<li>KV cache 仍保持 FP8/BF16，不随专家权重一起下探 4-bit——材料明确这一点，混淆会引入额外的精度风险。</li>\n<li>All-to-All 传输的激活与索引已按 4-bit 打包，带宽相比 FP8 减半的收益真正落到通信层。</li>\n</ul>\n<p>规模上限受两条约束夹住：outlier 敏感性随专家数与激活分布复杂度上升而恶化，scale 开销随分组 GEMM 调用次数上升而累积。材料未给出具体专家数上限，因此工程判断应落在“先小规模验证困惑度损失是否守在 &lt;1%，再按专家数扩展并监控路由打分漂移率”这条路径上，而不是预设一个数字。若扩展后困惑度损失突破阈值，回退顺序是先恢复激活到 FP8 而权重保留 NVFP4（半量化折中），再整体回 FP8；这条回退路径的代价是带宽收益减半，但保留了权重侧的显存节省。</p>\n<p>最终落到一个具体机制上：选型的实质是判断“减半的字节数是否真的转化为减半的读取时间”。只有当 scale 反量化被融合进 tcgen05 FP4 MMA 的累加前流程、且分组形状对齐 16 元素块时，<span class=\"inline-math\">\\(t_{\\text{read}}\\)</span> 的减半才不会被额外 kernel 抵消；任何让 scale 处理脱离主 MMA 流水线的实现，都会把这条算法从“带宽减半”退化成“带宽减半但延迟不变”。</p>\n\n<h3 id=\"alg-nvfp4-moe-quant-sec-49\">四十九 · 选型边界：NVFP4 与 FP8、INT4 分组量化、AWQ/GPTQ 的分工</h3>\n<p>把 NVFP4 放进同族算法谱系里，先要认清它替换的是哪一段成本。FP8 权重已压到 1 字节，decode 阶段每 token 仍要读全部激活专家的权重，瓶颈落在显存带宽而非算力；INT4 分组量化（如 group_size=128 的对称/非对称整型）同样把权重压到 4-bit，但激活往往留在 FP8/BF16，GEMM 走整型或反量化到高精度再乘，tcgen05 上没有原生 INT4 MMA 路径，反量化开销落在 CUDA core 上。NVFP4 的关键差别是权重与激活同时 4-bit、块宽固定 16、scale 为 FP8，且 FP4 MMA 由 tcgen05 原生执行，累加器 FP32，块内按 scale 反量化。AWQ/GPTQ 一类是权重仅量化、以激活感知的缩放搜索保护显著通道，适合权重带宽受限但激活动态范围难压的场景；NVFP4 则是权重激活双量化，收益在 All-to-All 与专家权重读取两处同时兑现。选型的第一个判据不是精度，而是<strong>激活能否安全压到 4-bit</strong>：MoE 的激活按 token 分组量化、scale 随 token 进 dispatch 缓冲，若某层激活 outlier 集中在少数通道，per-tensor scale 会把整块动态范围拉爆，必须退到 per-token 或更细的 per-block scale。</p>\n<p>决策表按四个维度收敛，避免在“精度看起来够”与“吞吐看起来高”之间拍脑袋：</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>权重/激活位宽</th><th>MMA 路径</th><th>适用条件</th><th>主要失效条件</th></tr></thead><tbody><tr><td>FP8</td><td>8 / 8</td><td>tcgen05 FP8</td><td>激活 outlier 重、校准预算紧、KV cache 需与权重同精度对齐</td><td>decode 专家权重读取仍占带宽主体，tokens/s 提升见顶</td></tr><tr><td>NVFP4 微缩放</td><td>4 / 4（块 16，FP8 scale）</td><td>tcgen05 FP4 MMA</td><td>MoE decode 带宽受限、batch 足够大使 scale 开销摊薄、有离线校准与在线 per-token scale</td><td>outlier 导致路由打分漂移；小 batch 下反量化 kernel 与寄存器压力抵消收益</td></tr><tr><td>INT4 分组量化</td><td>4 / 8 或 4 / 16</td><td>反量化后高精度 MMA</td><td>权重带宽受限、激活分布平稳、无 FP4 硬件档位</td><td>反量化落在 CUDA core，GEMM 吞吐不随位宽线性提升</td></tr><tr><td>AWQ/GPTQ</td><td>4 / 高精度</td><td>反量化后 MMA</td><td>仅权重压缩、显存容量优先于算力</td><td>激活未压，All-to-All 与激活读取带宽不降</td></tr></tbody></table>\n<p>系统代价要按 batch 形态分开算。分组 GEMM 的浮点运算量为 $2 \\cdot M \\cdot N \\cdot K$，NVFP4 下 MMA 吞吐可达 FP8 的 2 倍，但每 16 元素块要读一个 FP8 scale，scale 字节数与权重字节数之比为 $1/8$，即权重流量从 1 字节/元素降到 0.5 字节/元素再加 0.0625 字节/元素，净降约 47%；激活侧同理。收益兑现的前提是这些流量真被 MMA 吃掉：小 batch decode 时每 token 的 GEMM 形状窄，反量化 scale 引入的额外 kernel 启动与寄存器压力占比不可忽略，吞吐收益被抵消，此时应回退 FP8 或让连续批处理把 batch 堆到 scale 开销可摊薄的水平。反过来，大 batch 下专家权重读取时间近似减半直接抬升 tokens/s，这是 NVFP4 最确定的战场。</p>\n<p>失效条件集中在三处，且都与“校准分布 vs 运行时分布”的错配有关。其一，4-bit 激活量化对 outlier 敏感，per-token 或 per-block scale 校准不当会让路由打分漂移、专家选择错误——路由打分本身若也走量化激活，误差会直接改变 top-k 集合，这不是精度损失而是语义路径改变，必须把路由打分留在高精度或单独校准。其二，权重离线校准与运行时激活分布不一致时，NVFP4 量化误差累积到 combine 后激活，逐层放大影响输出质量；工程上应把离线校准集覆盖到目标流量的真实 prompt 分布，并对 combine 后的反量化回 BF16 做逐层误差抽检。其三，规模上限受 outlier 敏感性与 scale 开销约束，材料未给出具体专家数上限，判断依据应是“每 token 激活专家数 × 块数 × scale 读取”是否已逼近 MMA 的有效吞吐。与容量因子、专家选择等路由算法正交这一点也要记住：NVFP4 只动量化维度，路由侧的负载均衡与容量因子该调还得调，不能指望量化把路由抖动一并吃掉。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · NVFP4/FP8权重与激活量化</td></tr><tr><td>解决什么</td><td>MoE 推理是显存带宽受限的，专家权重占显存主体；FP8 已把权重压到 1 字节，但 decode 阶段每 token…</td></tr><tr><td>一句话机制</td><td>采用 NVFP4（E2M1 + 每 16 元素共享 FP8 scale）的微缩放格式，权重与激活都量化到 4-bit，…</td></tr><tr><td>代价与失效</td><td>4-bit 激活量化对 outlier 敏感，需 per-token 或 per-block scale，校准不当会导致路由打分漂移、专家…</td></tr><tr><td>后继</td><td>分块预填与解码捎带</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-moe-quant · 共 8 个片段</p>\n";break;}}})();
